function renderInterview(i){
 const locked=db.interviews.some(prev=>prev.projectId===i.projectId&&prev.round<i.round&&prev.questions.some(q=>q.answer===null)),done=i.questions.every(q=>q.answer!==null);
 return `<h3>访谈第 ${i.round} 轮 · 示例</h3>${i.questions.map((q,n)=>`<div class="interview-question"><b>Q${n+1} ${esc(q.text)}</b> <span class="question-type">${esc(q.type)}</span><p>推荐答案：${esc(q.recommended)}</p>${q.answer!==null?`<p class="user-answer">你：${esc(q.answer)} · ${q.adopted?'采纳推荐答案':'逐题回答'}</p>`:`<label>你的回答<textarea id="interview-${i.id}-${q.id}" ${locked?'disabled':''}></textarea></label><button ${locked?'disabled':''} onclick="answerInterview(${js(i.id)},${js(q.id)},$('#interview-${esc(i.id)}-${q.id}').value)">记录 Q${n+1} 回答</button> <button ${locked?'disabled':''} onclick="answerInterview(${js(i.id)},${js(q.id)},${js(q.recommended)},true)">采纳 Q${n+1} 推荐答案</button>`}</div>`).join('')}${done?`<p>本轮已答完。${db.interviews.some(n=>n.projectId===i.projectId&&n.round===i.round+1)?'下一轮见下方。':'访谈问答已记录；共同理解的确认见对话。'}</p>`:`<button ${locked?'disabled':''} onclick="adoptInterview(${js(i.id)})">采纳推荐答案 · 本轮</button>${locked?'<p>请先答完上一轮。</p>':''}`}`;
}
function renderProposal(p){const editing=panels.proposalEdit===p.id,rejecting=panels.proposalReject===p.id;return `<h3>提议 · ${p.newScope?'新范围 · ':''}示例</h3><p class="organization-reason">组织理由：${esc(p.reason)}</p><div class="proposal-cards">${p.cards.map((c,n)=>`<article class="proposal-card"><b>${esc(c.title)}</b><p>规格摘要：${esc(c.requirements)}</p><p class="src">分组：${esc(c.groups.join('、'))} · 依赖：${esc(c.dependencies.map(id=>getCard(id)?.title||p.cards.find(c=>c.id===id)?.title||id).join('、')||'无')}</p>${editing?`<label>标题<input id="proposal-title-${n}" value="${esc(c.title)}"></label><label>需求<textarea id="proposal-req-${n}">${esc(c.requirements)}</textarea></label><label>分组<input id="proposal-group-${n}" value="${esc(c.groups.join('，'))}"></label>`:''}</article>`).join('')}</div>${p.status==='pending'?`<div class="actions"><button class="primary" onclick="resolveProposal(${js(p.id)},'confirmed')">确认</button><button onclick="proposalAction(${js(p.id)},'modify')">修改</button><button onclick="proposalAction(${js(p.id)},'reject')">驳回</button></div>${editing?`<button class="primary" onclick="saveProposalForm(${js(p.id)})">保存修改并确认整组</button>`:''}${rejecting?`<label>驳回理由<textarea id="proposal-reason" required></textarea></label><button onclick="resolveProposal(${js(p.id)},'rejected',{reason:$('#proposal-reason').value})">提交驳回</button>`:''}<p id="proposal-error" role="status"></p>`:`<p>你已${({confirmed:'确认',modified:'修改后确认',rejected:'驳回'}[p.status])}。${esc(p.rejectionReason||'')}</p><button onclick="decisionJump(${js(p.decisionId)})">查看对应决策</button>`}`;}
function renderQuestion(q){const gate=db.gates.find(g=>g.questionId===q.id);return `${gate?`<p class="question-type">决策关卡 · ${gate.status==='waiting'?'等待'+esc(gate.answerBy):'已关闭'} · 示例</p><p>选项：${gate.options.map(esc).join(' / ')}</p>`:''}<h3>${q.kind==='member'?`来自卡「${esc(getCard(q.cardId)?.title)}」的成员`:'项目负责人的提问'}</h3>${q.kind==='member'?`<p class="src">来自某个 agent：${esc(getAgent(db.members[getCard(q.cardId)?.memberId]?.agentId)?.name||'未记录')} · 经项目负责人转问 · 示例</p>`:''}<p>${esc(q.text)}</p><p>推荐答案：${esc(q.recommended)}</p>${q.answer!==null?`<p class="user-answer">你：${esc(q.answer)}</p>`:`<label>你的回答<textarea id="answer-${esc(q.id)}"></textarea></label><button onclick="answerQuestion(${js(q.id)},$('#answer-${esc(q.id)}').value)">回答</button> <button onclick="answerQuestion(${js(q.id)},${js(q.recommended)},true)">采纳推荐答案</button>`}`;}
function renderDelegated(d){return `<p>示例 · 代你做的决定：${esc(d.title)} ${d.revoked?'<span class="revoked">已撤销</span>':''}<button onclick="decisionJump(${js(d.id)})">查看决策记录</button>${d.revoked?'':` <button onclick="revokeDecision(${js(d.id)})">撤销</button>`}</p>`;}
function renderConversation(p){if(!panels.conversation)return '';return `<section class="project-dialog" role="${window.innerWidth<=760?'dialog':'complementary'}" ${window.innerWidth<=760?'aria-modal="true"':''} aria-labelledby="conversation-title" onkeydown="panelKeydown(event,'.project-dialog',closeConversation)"><header class="panel-header"><h2 id="conversation-title">项目对话</h2><button id="conversation-close" onclick="toggleConversation()">返回看板 · 收起对话</button></header><p class="src">你 ↔ 项目负责人 · 所有模拟内容均标示例</p><div class="conversation-messages">${p.conversation.slice().sort((a,b)=>a.time.localeCompare(b.time)).map(m=>`<article id="message-${esc(m.id)}" class="conversation-bubble ${m.speaker==='你'?'bubble-user':''}" tabindex="-1"><div class="src">${esc(m.speaker||'项目负责人')} · ${m.example?'示例 · ':''}${esc(m.time)}</div>${m.kind==='interview'?renderInterview(byId(db.interviews,m.ref)):m.kind==='proposal'?renderProposal(byId(db.proposals,m.ref)):m.kind==='question'?renderQuestion(byId(db.questions,m.ref)):m.kind==='delegated'?renderDelegated(byId(db.decisions,m.ref)):`<p>${esc(m.text)}</p>`}</article>`).join('')}</div>${p.id==='project-a'?`<button onclick="replayInterview(${js(p.id)})">重新演示访谈两轮 · 示例</button>`:''}<label>给项目负责人发消息<textarea id="chat-input" placeholder="补充需求或约束"></textarea></label><button class="primary" onclick="sendMessage(${js(p.id)})">发送</button></section>`;}
function decisionStats(decisions=db.decisions){const proposals=decisions.filter(d=>typeof d.adoptedAsIs==='boolean');return {total:proposals.length,adopted:proposals.filter(d=>d.adoptedAsIs&&!d.revoked).length,rate:proposals.length?Math.round(proposals.filter(d=>d.adoptedAsIs&&!d.revoked).length/proposals.length*100):0};}

// 成员、派单和按轮信箱；所有时间推进只来自演示按钮。
const ROUND_STATE={running:'运行中','waiting-workflow':'等待 workflow',idle:'空闲','needs-you':'需要你'};
const MEMBER_COLUMNS={'needs-you':'需要你',running:'运行中',completed:'完成',idle:'空闲'};
const MESSAGE_TYPES={status:'状态',dispatch:'派单',completion:'完成报告',escalation:'升级',question:'提问',heartbeat:'心跳'};
const DELIVERY_STATUS={pending:'待投递',delivered:'已投递',confirmed:'已确认',undeliverable:'无法送达'};
const DISPATCH_RESULT={success:'成功',failed:'失败',unknown:'状态不明',running:'进行中'};
const timelineFilters={member:'',card:'',group:'',type:''};
const sessionPanel={id:null,origin:null};
const getSession=id=>db.sessions[id];
const getDispatch=id=>db.dispatches.find(d=>d.id===id);
function cardSessions(c){return Object.values(db.sessions).filter(s=>s.role==='member'&&s.cardIds.includes(c.id));}
function currentOwnerSession(c){return cardSessions(c).find(s=>getDispatch(s.currentDispatchId)?.result==='running')||cardSessions(c).at(-1);}
function sessionPaused(s){return Boolean(s.pauseReasons.length||getProject(s.projectId)?.paused||s.cardIds.some(id=>getCard(id)?.status==='paused'));}
function memberColumn(s){return sessionPaused(s)?'idle':s.roundState==='needs-you'?'needs-you':s.completed?'completed':['running','waiting-workflow'].includes(s.roundState)?'running':'idle';}
function filteredSessions(p){const ids=new Set(filteredCards(p).map(c=>c.id));return Object.values(db.sessions).filter(s=>s.projectId===p.id&&s.role==='member'&&s.cardIds.some(id=>ids.has(id)));}
function pendingMessages(s){return db.messages.filter(m=>m.projectId===s.projectId&&m.deliveries.some(d=>d.sessionId===s.id&&d.status==='pending')).length;}
function sessionCaption(s){return sessionPaused(s)?'已暂停 · 原状态：'+(s.completed?'完成':ROUND_STATE[s.roundState]):s.completed?'完成':ROUND_STATE[s.roundState];}
function unknownDispatch(s){return getDispatch(s.currentDispatchId)?.result==='unknown';}
function unreadCount(projectId=null){return Object.values(db.sessions).filter(s=>s.role==='member'&&s.unread&&(!projectId||s.projectId===projectId)).length;}
function setUnread(kind,id,value=true,refresh=true){
 if(kind==='session'){const s=getSession(id);if(!s)return;s.unread=value;for(const cid of s.cardIds){const c=getCard(cid);c.unread=value||cardSessions(c).some(other=>other.unread);}}
 else {const c=getCard(id);if(!c)return;c.unread=value;for(const s of cardSessions(c))s.unread=value;}
 for(const n of db.notifications)if(kind==='session'?n.sessionId===id:n.cardId===id)n.unread=value;
 if(refresh)render();
}
function notifySession(s,text){setUnread('session',s.id,true,false);db.notifications.push({id:'notification-'+(++db.serial),projectId:s.projectId,sessionId:s.id,cardId:s.currentCardId,text:'示例 · '+text,time:simulationTime(s.projectId),unread:true,example:true});}
function renderUnread(c){return c.unread?'<span class="unread-marker">● 未读</span>':'';}
function renderStatusLine(c,compact=false){const text=c.statusLine||'尚未填写状态行';return `<p class="status-line" data-status-card="${esc(c.id)}">${compact?'<span class="sample-marker">示例</span> · '+esc(demoText(text)):esc(text)}</p>`;}
function updateStatusLine(id,text,actor='你',refresh=true){
 const c=getCard(id);text=String(text||'').trim();if(!c||!text)return {ok:false};if(c.statusLine===text)return {ok:true,unchanged:true};
 const before=c.statusLine;c.statusLine=text;(c.statusLineHistory||=[]).push({time:actor==='你'?now():simulationTime(c.projectId),actor,text,example:actor!=='你'});
 if(actor==='你'){const d=recordDecision(c.projectId,c.id,'编辑状态行：'+c.title,`修改前：${before}；修改后：${text}`);d.before=before;d.after=text;}
 if(refresh)render();return {ok:true};
}
function stageStatus(c,text){const constraints=c.statusLine.split('\n').filter(line=>/目标[：:]|约束[：:]/.test(line));const tail=constraints.map(line=>line.replace(/^.*?(?=(?:目标|约束)[：:])/,'')).join('\n');updateStatusLine(c.id,'示例 · '+demoText(text)+(tail?'\n'+tail:''),'示例 · 成员',false);}
function renderStatusEditor(c){return statusEditorState.cardId===c.id?`<section class="card status-editor"><h2>编辑状态行</h2><label>状态行（可写目标或约束）<textarea id="status-line-input">${esc(c.statusLine)}</textarea></label><div class="actions"><button onclick="updateStatusLine(${js(c.id)},$('#status-line-input').value)">保存状态行</button><button onclick="toggleStatusEditor(${js(c.id)},false)">收起编辑</button></div>${renderStatusHistory(c)}</section>`:'';}

function renderMembers(p){const sessions=filteredSessions(p);return `<div class="member-board" data-board-view="members">${Object.entries(MEMBER_COLUMNS).map(([column,label])=>`<section class="member-column member-${column}" data-member-column="${column}"><h2>${label} · ${sessions.filter(s=>memberColumn(s)===column).length}</h2>${sessions.filter(s=>memberColumn(s)===column).map(s=>{s.pendingCount=pendingMessages(s);const c=getCard(s.currentCardId);return `<article class="member-card ${unknownDispatch(s)?'has-unknown':''}" data-session-id="${esc(s.id)}" data-card-id="${esc(c.id)}" data-round-state="${esc(s.roundState)}"><button class="card-title" onclick="openSession(${js(s.id)},event.currentTarget)">${esc(sessionName(s))}</button>${s.unread?'<span class="unread-marker">● 未读</span>':''}<p><button data-focus-key="member-card-detail-${esc(s.id)}" onclick="go('card',${js(c.id)},event.currentTarget)">卡片详情</button> ${chip(c.status)} <span class="src">${dispatchCaption(s)}</span></p>${sessionPaused(s)?`<p class="pause-marker">${esc(sessionCaption(s))}</p>`:s.roundState==='waiting-workflow'?'<p>等待 workflow</p>':''}${renderStatusLine(c,true)}<div class="meta">花费 ¥${s.spent.toFixed(2)} · 待投递消息 ${s.pendingCount}</div>${unknownDispatch(s)?'<p class="dispatch-unknown">⚠ 状态不明 · 未收到完成报告</p>':''}${s.pauseReasons.length?'<span class="pause-marker">成员已暂停</span>':''}</article>`;}).join('')||'<p>暂无会话</p>'}</section>`).join('')}</div>`;}
function openSession(id,trigger){const s=getSession(id);if(!s)return;sessionPanel.origin=focusDescriptor(trigger||document.activeElement);sessionPanel.id=id;setUnread('session',id,false,false);render();$('#session-close')?.focus?.();}
function closeSession(){const origin=sessionPanel.origin;sessionPanel.id=null;sessionPanel.origin=null;render();restoreDescriptor(origin,'#board-surface');}
function renderDispatch(d){return `<article class="dispatch-record ${d.result==='unknown'?'dispatch-unknown':''}" data-dispatch-id="${esc(d.id)}"><h3>派单 ${d.number} · ${DISPATCH_RESULT[d.result]}${d.score?' · '+esc(d.score):''} ${d.example?'· 示例':''}</h3><p>${esc(d.method)}</p>${d.failure?`<p class="changed">${esc(d.failure)}</p>`:''}<p class="src">会话：${esc(d.sessionKey)} · 真实会话 ID：${esc(d.sessionId||'未记录')} · 代理：${esc(getAgent(d.agentId)?.name||d.agentId)} · 模型：${esc(d.model||'未记录')}</p><p>工作区：${esc(d.workspace.description)} · 基线：${esc(d.workspace.baseline)}</p><p class="src">开始：${esc(d.startedAt||'未记录')} · 结束：${esc(d.endedAt||'未记录')} · 心跳：${esc(d.heartbeatAt||'尚无')} · 花费：${d.cost==null?'未记录':'示例 ¥'+d.cost}</p>${d.completionReport?`<section class="completion-report" data-report-id="${esc(d.completionReport.id)}"><h3>完成报告 · ${DISPATCH_RESULT[d.completionReport.result]} · 示例格式</h3><p>${esc(d.completionReport.summary)}</p><p>改了哪些文件：${esc(d.completionReport.changedFiles.join('、')||'未记录 / 无文件改动（见出处）')}</p></section>`:`<p class="${d.result==='unknown'?'dispatch-unknown':'src'}">${esc(d.reportNote||'派单进行中，尚未发完成报告')}</p>`}<p class="src">出处：${esc((d.sourceFiles||[]).join('；')||'示例')}</p></article>`;}
function renderSessionPanel(){const s=getSession(sessionPanel.id);if(!s)return '';const c=getCard(s.currentCardId),d=getDispatch(s.currentDispatchId),mail=db.messages.filter(m=>m.fromSession===s.id||m.deliveries.some(r=>r.sessionId===s.id));return `<div class="session-backdrop" onclick="if(event.target===this){event.preventDefault();closeSession();}"><section class="session-detail" role="dialog" aria-modal="true" aria-labelledby="session-heading" onkeydown="panelKeydown(event,'.session-detail',closeSession)"><header class="panel-header"><h2 id="session-heading">${esc(sessionName(s))} · 会话输出 <span class="sample-marker">示例</span></h2><button id="session-close" onclick="closeSession()">关闭会话</button></header><p>${esc(s.id)} · 真实会话 ID：${esc(s.externalId||'未记录')} · ${esc(sessionCaption(s))}</p><div class="actions">${cardLink(c.id)}<button onclick="togglePause('session',${js(s.id)})">${s.pauseReasons.includes('session:'+s.id)?'恢复成员':'暂停成员'}</button><button onclick="setUnread('session',${js(s.id)},true)">重新标为未读</button><button onclick="simulateNextRound(${js(s.projectId)})">模拟下一轮 · 演示用</button></div><p class="status-line">${esc(demoText(c.statusLine))}</p><h3>实时输出 · 预设片段</h3><div id="session-output" class="session-output" tabindex="0" aria-label="会话实时输出">${s.output.map(o=>`<div class="output-line"><time>${esc(o.time)}</time><pre>${esc(o.text)}</pre></div>`).join('')}</div><h3>当前派单</h3>${d?compactRecordMarkup(renderDispatch(d)):'<p>尚未派单</p>'}<h3>信箱</h3>${mail.map(m=>compactRecordMarkup(renderMail(m,s.id))).join('')||'<p>暂无消息</p>'}${renderMailComposer(s)}</section></div>`;}
function renderMailComposer(s){const p=getProject(s.projectId);return `<section class="card"><h3>发送消息</h3><label>收件人<select id="mail-recipient">${Object.values(db.sessions).filter(r=>r.projectId===p.id&&r.id!==s.id).map(r=>`<option value="session:${esc(r.id)}">会话 · ${esc(sessionName(r))} · ${dispatchCaption(r)}${r.hasMailbox?'':'（无信箱）'}</option>`).join('')}${projectCards(p).map(c=>`<option value="card-owner:${esc(c.id)}">卡片负责人 · ${esc(c.title)}</option>`).join('')}${['all','idle',...new Set(projectCards(p).flatMap(c=>c.groups))].map(g=>`<option value="group:${esc(g)}">分组 · ${g==='all'?'全队':g==='idle'?'空闲的成员':esc(g)}</option>`).join('')}</select></label><label>消息类型<select id="mail-type">${['status','question','escalation'].map(t=>`<option value="${t}">${MESSAGE_TYPES[t]}</option>`).join('')}</select></label><label>内容<textarea id="mail-content"></textarea></label><button onclick="sendSessionMail(${js(s.id)},$('#mail-recipient').value,$('#mail-type').value,$('#mail-content').value)">写入信箱 · 等下一轮投递</button><p id="mail-error" role="status"></p></section>`;}
function addressSessions(projectId,recipient){const sessions=Object.values(db.sessions).filter(s=>s.projectId===projectId);if(recipient.kind==='session')return sessions.filter(s=>s.id===recipient.id);if(recipient.kind==='card-owner'){const c=getCard(recipient.id);return c?.projectId===projectId?[currentOwnerSession(c)].filter(Boolean):[];}if(recipient.kind==='group')return sessions.filter(s=>s.role==='member'&&(recipient.id==='all'||recipient.id==='idle'&&memberColumn(s)==='idle'&&!sessionPaused(s)||s.cardIds.some(id=>getCard(id)?.groups.includes(recipient.id))));return [];}
function initializeDelivery(m){if(m.deliveries.length||m.status==='undeliverable'||m.status==='confirmed')return;const recipients=addressSessions(m.projectId,m.recipient);m.deliveries=recipients.map(s=>({sessionId:s.id,status:s.hasMailbox?'pending':'undeliverable',reason:s.hasMailbox?'':'示例 · 收件会话没有信箱',readyAfterRound:s.round+1,deliveredAt:null,confirmedAt:null}));if(!recipients.length){m.status='undeliverable';m.reason='示例 · 收件地址没有可用会话';}syncDelivery(m);}
function syncDelivery(m){if(!m.deliveries.length)return;const good=m.deliveries.filter(d=>d.status!=='undeliverable');m.reason=m.deliveries.filter(d=>d.reason).map(d=>d.reason).join('；');m.status=!good.length?'undeliverable':good.some(d=>d.status==='pending')?'pending':good.every(d=>d.status==='confirmed')?'confirmed':'delivered';}
function queueMail(projectId,type,fromSession,recipient,cardIds,content,extra={}){
 const sender=getSession(fromSession),p=getProject(projectId);if(!p||sender?.projectId!==projectId||!MESSAGE_TYPES[type])return {ok:false,reason:'发件会话或项目无效'};
 if(['completion','heartbeat'].includes(type)&&(recipient.kind!=='session'||recipient.id!==p.leaderSessionId))return {ok:false,reason:'完成报告和心跳只发给派单的项目负责人'};
 const m=seedMail('mail-'+(++db.serial),projectId,type,fromSession,recipient,cardIds,content);Object.assign(m,extra,{time:simulationTime(projectId)});initializeDelivery(m);refreshPendingCounts();return m;
}
function sendSessionMail(id,address,type,content){const s=getSession(id);content=String(content||'').trim();if(!s||!content){$('#mail-error').textContent='请填写消息内容';return {ok:false};}const split=address.indexOf(':'),recipient={kind:address.slice(0,split),id:address.slice(split+1)};const m=queueMail(s.projectId,type,id,recipient,s.cardIds.slice(),'示例 · '+content);render();return m;}
function refreshPendingCounts(){for(const s of Object.values(db.sessions))s.pendingCount=pendingMessages(s);}
function confirmMail(id,sessionId){const m=byId(db.messages,id),d=m?.deliveries.find(d=>d.sessionId===sessionId);if(!d||d.status!=='delivered')return {ok:false};d.status='confirmed';d.confirmedAt=simulationTime(m.projectId);m.confirmedAt=d.confirmedAt;syncDelivery(m);render();return {ok:true};}
function simulationTime(projectId){return new Date(Date.UTC(2026,9,13,9,getProject(projectId)?.demoRound||0)).toISOString().replace('T',' ').slice(0,19);}
function recipientLabel(m){const r=m.recipient;return r.kind==='session'?`会话：${getAgent(getSession(r.id)?.agentId)?.name||r.id} · ${r.id}`:r.kind==='card-owner'?`卡片负责人：${getCard(r.id)?.title||r.id}`:`一组：${r.id==='all'?'全队':r.id==='idle'?'空闲的成员':r.id}`;}
function renderMail(m,sessionId=null){const sender=getSession(m.fromSession),bad=m.status==='undeliverable'||m.reason;return `<article class="mail-message ${bad?'message-undeliverable':''}" data-message-id="${esc(m.id)}" data-message-type="${esc(m.type)}" data-delivery-status="${esc(m.status)}"><span class="message-type mt-${m.type}">${MESSAGE_TYPES[m.type]}</span> <span class="delivery-status ds-${m.status}">${DELIVERY_STATUS[m.status]}</span><p class="src">${esc(m.time)} · 发件会话 ${esc(m.fromSession)} · 来自某个 agent：${esc(getAgent(sender?.agentId)?.name||'未记录')} · ${m.example?'示例':''}</p><p>收件人：${esc(recipientLabel(m))}</p><p>${esc(m.content)}</p>${m.cardIds.map(cardLink).join(' ')}${askButton('message',m.id,m.projectId)}${bad?`<p class="delivery-error">无法送达原因：${esc(m.reason)}</p>`:''}${m.deliveries.length?`<details><summary>各收件会话的投递状态</summary>${m.deliveries.map(d=>`<p>${esc(d.sessionId)} · ${DELIVERY_STATUS[d.status]}${d.reason?' · '+esc(d.reason):''}</p>`).join('')}</details>`:''}${sessionId&&m.deliveries.some(d=>d.sessionId===sessionId&&d.status==='delivered')?`<button onclick="confirmMail(${js(m.id)},${js(sessionId)})">确认已处理</button>`:''}</article>`;}
function filteredMessages(projectId){const f=timelineFilters;return db.messages.filter(m=>m.projectId===projectId&&(!f.member||m.fromSession===f.member||m.deliveries.some(d=>d.sessionId===f.member)||m.recipient.kind==='session'&&m.recipient.id===f.member)&&(!f.card||m.cardIds.includes(f.card)||m.recipient.kind==='card-owner'&&m.recipient.id===f.card)&&(!f.group||m.groupNames.includes(f.group)||m.recipient.kind==='group'&&m.recipient.id===f.group)&&(!f.type||m.type===f.type)).slice().sort((a,b)=>a.time.localeCompare(b.time));}
function setTimelineFilter(key,value){if(Object.hasOwn(timelineFilters,key)){timelineFilters[key]=value;render();}}
function renderTimeline(p){const options=(items,key)=>`<option value="">全部</option>`+items.map(([id,text])=>`<option value="${esc(id)}" ${timelineFilters[key]===id?'selected':''}>${esc(text)}</option>`).join('');$('#main').innerHTML=`${crumb(p,'消息时间线')}${renderRuntimeHeader(p)}<h1>消息时间线</h1>${askButton('timeline',p.id,p.id)}<p class="src">按轮投递；未确认的信件保留在信箱。成员消息均来自某个 agent · 示例</p><div class="card filters"><label>成员 / 会话<select id="timeline-member" onchange="setTimelineFilter('member',this.value)">${options(Object.values(db.sessions).filter(s=>s.projectId===p.id).map(s=>[s.id,sessionName(s)+' · '+dispatchCaption(s)]),'member')}</select></label><label>卡片<select id="timeline-card" onchange="setTimelineFilter('card',this.value)">${options(projectCards(p).map(c=>[c.id,c.title]),'card')}</select></label><label>分组<select id="timeline-group" onchange="setTimelineFilter('group',this.value)">${options(['all','idle',...new Set(projectCards(p).flatMap(c=>c.groups))].map(g=>[g,g==='all'?'全队':g==='idle'?'空闲的成员':g]),'group')}</select></label><label>消息类型<select id="timeline-type" onchange="setTimelineFilter('type',this.value)">${options(Object.entries(MESSAGE_TYPES),'type')}</select></label><button onclick="resetTimelineFilters()">清除消息筛选</button></div><div class="message-timeline">${filteredMessages(p.id).map(m=>renderMail(m)).join('')||'<p>没有匹配消息</p>'}</div>`;}
function resetTimelineFilters(){Object.keys(timelineFilters).forEach(k=>timelineFilters[k]='');render();}
function renderRuntimeHeader(p){return `<div class="runtime-header"><span id="unread-count">未读 ${unreadCount(p.id)}</span>${renderPauseSummary(p)}${renderRuntimeNotices(p.id)}<button onclick="togglePause('project',${js(p.id)})">${p.paused?'恢复项目':'暂停项目'}</button><button class="demo-round" onclick="simulateNextRound(${js(p.id)})">模拟下一轮 · 演示用</button><span class="src">第 ${p.demoRound||0} 轮 · 示例</span></div>`;}
function renderTeam(p){$('#main').innerHTML=`${crumb(p,'团队')}${renderRuntimeHeader(p)}<h1>团队</h1><p class="src">代理与成员配置、预算与表现统计为示例；历史会话 ID 缺失时保持未记录。</p>${Object.values(db.members).filter(m=>getCard(m.cardId)?.projectId===p.id).map(m=>{const c=getCard(m.cardId),a=getAgent(m.agentId),ss=cardSessions(c),ds=c.dispatches||c.attempts;return `<section class="card team-member" data-member-id="${esc(m.id)}"><h2>${esc(m.name)} · ${esc(c.title)} <span class="sample-marker">示例</span></h2><p>代理配置：${esc(a.name)} · ${esc(a.executor)} · 主模型 ${esc(a.mainModel||a.model)} · 强度 ${esc(a.mainStrength||a.strength)}</p><p>${esc(a.instructions)}</p><p>当前卡：${cardLink(c.id)}</p><p>预算 ¥${c.budget} · 花费 ¥${c.spent.toFixed(2)}</p><p class="team-stats">表现统计：派单 ${ds.length} · 成功 ${ds.filter(d=>d.result==='success').length} · 失败 ${ds.filter(d=>d.result==='failed').length} · 状态不明 ${ds.filter(d=>d.result==='unknown').length}</p>${ss.map(s=>`<div class="row"><button onclick="openSession(${js(s.id)},event.currentTarget)">会话详情 · ${dispatchCaption(s)}</button><span class="src"> · ${esc(sessionCaption(s))}</span><p>会话预算 ¥${s.budget} · 花费 ¥${s.spent.toFixed(2)} · 待投递 ${pendingMessages(s)}</p>${unknownDispatch(s)?'<p class="dispatch-unknown">状态不明</p>':''}<button onclick="togglePause('session',${js(s.id)})">${s.pauseReasons.includes('session:'+s.id)?'恢复成员':'暂停成员'}</button>${s.unread?'<span class="unread-marker">● 未读</span>':''}</div>`).join('')}</section>`;}).join('')||'<p>尚无成员</p>'}`;}
function renderRecords(c){return `<section class="card status-history"><h2>状态行历史</h2>${renderStatusHistory(c)}</section><section class="card"><h2>上下文包</h2>${(c.contextPackages||[]).map(p=>`<article class="row"><h3>${esc(p.dispatchId)} · 示例</h3><p>发了什么：${esc(p.sent.join('、'))}</p><p>没发什么及原因：${esc(p.omitted.map(o=>o.item+'：'+o.reason).join('；'))}</p></article>`).join('')||'<p>尚未派单，没有上下文包</p>'}</section><section class="card"><h2>相关消息</h2>${db.messages.filter(m=>m.cardIds.includes(c.id)).map(m=>renderMail(m)).join('')||'<p>暂无消息</p>'}</section>${[['handoffs','交接记录'],['findings','发现']].map(([key,label])=>`<section class="card"><h2>${label}</h2>${(c[key]||[]).map(r=>`<p>${esc(r.time)} · ${esc(r.text)}</p>`).join('')||'<p>暂无记录</p>'}</section>`).join('')}<section class="card"><h2>相关决策</h2>${db.decisions.filter(d=>d.cardId===c.id||d.affectedCardIds?.includes(c.id)).map(d=>`<div class="row"><button onclick="decisionJump(${js(d.id)})">${esc(d.title)}</button><p>${esc(d.reason)} · ${esc(d.decisionMaker)}</p></div>`).join('')||'<p>暂无决策</p>'}</section><section class="card"><h2>派单列表 · 一次派单就是一次尝试</h2>${(c.dispatches||c.attempts).map(renderDispatch).join('')||'<p>尚未派单</p>'}</section><section class="card"><h2>决策关卡</h2>${db.gates.filter(g=>g.cardId===c.id).map(g=>`<p>${esc(g.question)} · ${g.status==='waiting'?'等待'+g.answerBy:'已关闭 · '+esc(g.answeredBy)} · 示例</p>`).join('')||'<p>无关卡</p>'}</section>`;}
function renderFiles(c){return `<section class="card"><h2>相对基线的改动文件</h2>${c.registeredTests.filter(t=>t.modifiedByExecutor).map(t=>`<p class="changed">runtime 单独标出：${esc(t.path)} · 示例 · 被执行方改过的登记测试文件（执行方只读）</p>`).join('')}<p>基线：${esc(c.fileBaseline||'未记录')}</p>${(c.fileChanges||[]).map(f=>`<article class="row"><h3>${esc(f.path)} ${f.example?'· 示例':''}</h3><p>${esc(f.note)}</p>${previewReference(f.preview,'artifact')}${renderAnnotatedFile(c,f)}</article>`).join('')||'<p>尚无已记录的文件差异；不将未知文件列表视为没有改动。</p>'}${!(c.fileChanges||[]).length?renderAnnotatedFile(c,annotationFiles(c)[0]):''}</section>${renderAnnotationComposer(c)}<section class="card"><h2>并行步骤的合回记录</h2>${(c.mergeRecords||[]).map(r=>`<p>${esc(r.time)} · ${esc(r.steps.join('、'))} · ${esc(r.result)}</p>`).join('')||'<p>没有已记录的并行合回</p>'}</section>`;}
function changeCardPause(c,reason,on){c.pauseReasons||=[];if(on){if(!c.pauseReasons.includes(reason)){if(c.status!=='paused')c.beforePauseStatus=c.status;c.pauseReasons.push(reason);c.status='paused';}}else{c.pauseReasons=c.pauseReasons.filter(r=>r!==reason);if(!c.pauseReasons.length&&c.status==='paused'){c.status=c.beforePauseStatus||'running';c.beforePauseStatus=null;}}}
function togglePause(scope,id){
 const project=scope==='project'?getProject(id):getProject(scope==='card'?getCard(id)?.projectId:getSession(id)?.projectId);if(!project)return {ok:false};let on,label,cardId=null;
 if(scope==='project'){on=!project.paused;project.paused=on;label=project.name;for(const c of projectCards(project))if(!['accepted','integrated','cancelled'].includes(c.status)||c.pauseReasons?.includes('project:'+id))changeCardPause(c,'project:'+id,on);}
 else if(scope==='card'){const c=getCard(id);if(c.status==='cancelled')return {ok:false,reason:'已取消卡片不能恢复'};cardId=id;label=c.title;const initial=c.pauseReasons?.includes('budget:a-budget');on=!c.pauseReasons?.includes('card:'+id)&&!initial;if(initial){if(db.hardItems.some(h=>h.id==='a-budget'&&h.status==='pending')){flowEditor.notice='请先在收件箱处理预算上限，再恢复卡片。';flowEditor.noticeKind='error';render();return {ok:false};}changeCardPause(c,'budget:a-budget',false);}else changeCardPause(c,'card:'+id,on);}
 else if(scope==='session'){const s=getSession(id);if(!s||s.role!=='member')return {ok:false};const reason='session:'+id;on=!s.pauseReasons.includes(reason);s.pauseReasons=on?[...s.pauseReasons,reason]:s.pauseReasons.filter(r=>r!==reason);cardId=s.currentCardId;label=sessionName(s)+' · '+dispatchCaption(s);changeCardPause(getCard(cardId),reason,on);}
 else return {ok:false};
 recordDecision(project.id,cardId,(on?'暂停':'恢复')+({project:'项目',card:'卡片',session:'成员'}[scope])+'：'+label,'保留暂停前状态；各范围暂停分别记录，恢复后仍受其他暂停范围约束。');flowEditor.menu=null;render();return {ok:true,paused:on};
}
function finishDispatch(id,result,summary,changedFiles=[]){const d=getDispatch(id);if(!d||d.result!=='running'||d.completionReport||!['success','failed'].includes(result))return {ok:false,reason:'派单不能重复发送完成报告'};d.result=result;d.endedAt=simulationTime(d.projectId);d.completionReport={id:'report-'+d.id,result,summary,changedFiles:changedFiles.slice(),time:d.endedAt,example:true};const s=getSession(d.sessionKey),c=getCard(d.cardId);s.completed=true;s.roundState='idle';s.output.push({time:d.endedAt,text:'示例 · 完成报告：'+summary});queueMail(d.projectId,'completion',s.id,{kind:'session',id:getProject(d.projectId).leaderSessionId},[c.id],summary,{dispatchId:d.id,reportId:d.completionReport.id});stageStatus(c,summary+'；派单已完成，等待项目负责人处理');notifySession(s,c.title+'的派单已完成');return {ok:true};}
function resolveGateForQuestion(q,actor='你') {const g=db.gates.find(g=>g.questionId===q.id&&g.status==='waiting');if(!g)return;g.status='closed';g.answer=q.answer;g.answeredBy=actor;g.answeredAt=now();const c=getCard(g.cardId);if(c.status==='paused')c.beforePauseStatus=g.resumeStatus;else c.status=g.resumeStatus;for(const s of cardSessions(c))if(s.roundState==='needs-you'&&!unknownDispatch(s)){s.roundState=getDispatch(s.currentDispatchId)?.result==='running'?'running':'idle';}stageStatus(c,'已收到关卡回答，继续处理：'+q.answer);}
function answerGate(id,answer,actor='你'){const g=byId(db.gates,id);answer=String(answer||'').trim();if(!g||g.status!=='waiting'||actor!==g.answerBy||!answer)return {ok:false};if(actor==='你')return answerQuestion(g.questionId,answer);const q=byId(db.questions,g.questionId);q.answer=answer;resolveGateForQuestion(q,actor);const d=recordDecision(g.projectId,g.cardId,'回答决策关卡：'+g.question,answer);d.decisionMaker=actor;d.outcome='已回答';render();return {ok:true};}
function simulateNextRound(projectId){
 const p=getProject(projectId);if(!p)return {ok:false};if(p.paused){flowEditor.notice='示例 · 项目已暂停，本轮没有推进。';flowEditor.noticeKind='neutral';render();return {ok:false,paused:true};}
 const eligible=Object.values(db.sessions).filter(s=>s.projectId===p.id&&s.hasMailbox&&!sessionPaused(s));p.demoRound=(p.demoRound||0)+1;const time=simulationTime(p.id);
 // 先冻结本轮待投递集合；本轮产生的新信件留到收件人的下一个边界。
 const pending=db.messages.filter(m=>m.projectId===p.id&&m.status==='pending');for(const m of pending)initializeDelivery(m);
 for(const s of eligible)s.round++;
 for(const m of pending){for(const d of m.deliveries){const s=getSession(d.sessionId);if(d.status==='pending'&&eligible.includes(s)&&s.round>=d.readyAfterRound){d.status='delivered';d.deliveredAt=time;m.deliveredAt=time;s.output.push({time,text:'示例 · 本轮信箱收到：'+m.content});}}syncDelivery(m);}
 for(const s of eligible){const d=getDispatch(s.currentDispatchId);if(d?.result!=='running'||s.roundState==='needs-you')continue;
 d.heartbeatAt=time;s.spent+=.05;d.cost=(d.cost||0)+.05;const c=getCard(d.cardId);c.spent+=.05;s.output.push({time,text:'示例 · 心跳：正在处理「'+c.title+'」，轮次 '+s.round});queueMail(p.id,'heartbeat',s.id,{kind:'session',id:p.leaderSessionId},[c.id],'示例 · '+c.statusLine,{dispatchId:d.id});
 if(c.id==='a-capacity'&&s.round>=2&&!db.messages.some(m=>m.replyTo==='a-person-days')&&db.messages.find(m=>m.id==='a-person-days')?.deliveries.some(r=>r.sessionId===s.id&&r.status==='delivered')){const question=byId(db.messages,'a-person-days'),delivery=question.deliveries.find(r=>r.sessionId===s.id);delivery.status='confirmed';delivery.confirmedAt=time;question.confirmedAt=time;syncDelivery(question);queueMail(p.id,'status',s.id,{kind:'card-owner',id:'a-cost'},['a-capacity','a-cost'],'示例 · 交付估算 28 人天，另留 20% 缓冲；依据资源台账与 Q4 排期。',{replyTo:question.id});finishDispatch(d.id,'success','示例 · 已完成人天估算：28 人天与 20% 缓冲',[]);}
 if(c.id==='a-cost'&&db.messages.some(m=>m.replyTo==='a-person-days'&&m.deliveries.some(r=>r.sessionId===s.id&&r.status==='delivered'))){finishDispatch(d.id,'success','示例 · 已收到人天估算，完成成本区间整理',[]);}
 if(c.id==='b-defect-diagnose'&&s.round===1){const q=byId(db.questions,'b-member-question');if(q.answer===null){s.roundState='needs-you';s.output.push({time,text:'示例 · 已升级检查范围问题给项目负责人，由项目负责人转问你'});stageStatus(c,'已定位溢出，等待你确认 320px 检查范围');queueMail(p.id,'question',s.id,{kind:'session',id:p.leaderSessionId},[c.id],q.text);notifySession(s,c.title+'需要你回答');}else finishDispatch(d.id,'success','示例 · 已确认检查范围并完成诊断',[]);}
 else if(c.id==='b-defect-diagnose'&&s.round>=2&&byId(db.questions,'b-member-question').answer!==null)finishDispatch(d.id,'success','示例 · 已按回答完成诊断，等待项目负责人安排修复',[]);
 }
 p.spent=projectCards(p).reduce((sum,c)=>sum+c.spent,0);refreshPendingCounts();render();return {ok:true,round:p.demoRound};
}
const notificationState={};
function demoText(value){return String(value||'').replace(/(?:示例\s*[·：:]\s*)+/g,'').trim();}
function compactRecordMarkup(markup){const cleaned=markup.split(/(<[^>]*>)/g).map(part=>part.startsWith('<')?part:part.replace(/(?:示例\s*[·：:]\s*)+/g,'').replace(/\s*·\s*示例(?:格式|配置)?/g,'').replace(/示例/g,'预设')).join('');return cleaned.replace(/^(<article[^>]*>)/,'$1<span class="sample-marker">示例</span>');}
function sessionName(s){return (getAgent(s.agentId)?.name||'成员')+' · '+(getCard(s.currentCardId)?.title||(s.role==='coordinator'?'项目协调':'辅助会话'));}
function dispatchCaption(s){const d=getDispatch(s.currentDispatchId);return d?'派单 '+d.number:'尚未派单';}
function renderBoardToolbar(p){return `<div class="toolbar board-toolbar"><div class="board-toolbar-primary"><button class="primary" data-flow-add onclick="flowAddInput(event.currentTarget)">＋ 新建卡</button>${view.board==='graph'?`<button onclick="${flowEditor.editing?'leaveFlowEdit()':'enterFlowEdit()'}">${flowEditor.editing?'结束编辑':'编辑看板'}</button>`:''}</div>${view.board==='graph'?`<div class="src board-instructions">${flowViewport().vertical?'窄屏请使用卡片菜单添加依赖':'编辑时可从连接点拖到目标卡片'}；操作立即生效。</div>`:''}<div class="board-toolbar-demo"><span class="src board-count">${filteredCards(p).length}/${p.cardIds.length} 张卡片</span><button class="demo-round" onclick="simulateNextRound(${js(p.id)})">模拟下一轮 · 演示用</button><span class="src board-round">第 ${p.demoRound||0} 轮 · 示例</span></div></div>`;}
function pausedItems(p){const cards=projectCards(p).filter(c=>c.status==='paused'),sessions=Object.values(db.sessions).filter(s=>s.projectId===p.id&&s.role==='member'&&s.pauseReasons.length);return {cards,sessions};}
function renderPauseSummary(p){const {cards,sessions}=pausedItems(p);return `${p.paused?'<span class="pause-marker">项目已暂停</span>':''}${cards.length||sessions.length?`<details class="pause-summary"><summary class="pause-marker">已暂停：${cards.length} 张卡、${sessions.length} 个成员</summary><div class="pause-list"><h3>暂停的卡片</h3>${cards.map(c=>`<p>${cardLink(c.id)}</p>`).join('')||'<p>无</p>'}<h3>单独暂停的成员</h3>${sessions.map(s=>`<p><button onclick="openSession(${js(s.id)},event.currentTarget)">${esc(sessionName(s))} · ${dispatchCaption(s)}</button></p>`).join('')||'<p>无</p>'}</div></details>`:''}`;}
function dismissNotification(id){const n=byId(db.notifications,id);if(n)n.dismissed=true;render();}
function notificationToggle(el,key){notificationState[key]=el.open;}
function closeNotifications(key){notificationState[key]=false;render();$('#notifications-'+key)?.focus?.();}
function renderRuntimeNotices(projectId=null){const key=projectId||'all',list=db.notifications.filter(n=>n.unread&&!n.dismissed&&(!projectId||n.projectId===projectId)).slice(-3);return list.length?`<details class="notification-center" ${notificationState[key]?'open':''} ontoggle="notificationToggle(this,${js(key)})"><summary id="notifications-${esc(key)}" role="status">通知 ${list.length}</summary><aside class="runtime-notices" aria-label="会话通知"><div class="notification-actions"><button onclick="closeNotifications(${js(key)})">收起通知</button></div>${list.map(n=>`<div class="notification-row"><span class="src">${esc(getProject(n.projectId)?.name)}</span><button onclick="openSession(${js(n.sessionId)},event.currentTarget)">${esc(demoText(n.text))}</button><button aria-label="关闭这条通知" onclick="dismissNotification(${js(n.id)})">关闭通知</button></div>`).join('')}<p class="src">关闭提示不清除未读；同时最多显示 3 条。</p></aside></details>`:'';}
for(const m of db.messages)initializeDelivery(m);refreshPendingCounts();

function ensureCardRuntime(c){ensureAcceptance(c);c.dispatches||=c.attempts;c.dispatchIds||=[];c.statusLineHistory||=[{time:now(),actor:'你',text:c.statusLine,example:false}];c.pauseReasons||=[];c.unread||=false;}
function renderDispatchExecution(c){return `<section class="card"><h2>派单与会话</h2>${(c.dispatches||c.attempts).map(d=>`<button onclick="openSession(${js(d.sessionKey)},event.currentTarget)">查看派单 ${d.number} 的实时输出</button>${renderDispatch(d)}`).join('')||'<p>尚未派单</p>'}</section>`;}
// 第 4 批：内存中的 runtime 模拟。提交、验证快照、批注锚点相互独立。
const CARD_TABS=[['spec','规格'],['dependencies','依赖'],['execution','执行'],['acceptance','验收'],['files','文件'],['records','记录']];
const AUTO_CONDITIONS={verification:'独立验证通过',deterministic:'确定性测试全部通过',noJudgment:'没有判断型测试',noCore:'没有标出核心业务逻辑改动',noTestEdits:'项目负责人没有改过测试'};
const acceptanceUI={actor:'项目负责人',agentId:'agent-check',method:'按规格复核产物与证据',changeModel:true,preset:'current',selection:null,composer:null};
function ensureAcceptance(c){
 c.currentCommit||='示例-提交-'+c.id+'-1';c.artifactRevision||=1;c.verifications||=[];c.annotations||=[];c.modificationRequests||=[];c.registeredTests||=[];c.coreChanges||=[];c.testEdits||=[];c.acceptanceNotice||='';
 const p=getProject(c.projectId);p.baselineRevision||=1;p.autoAcceptanceSettings||={enabled:false,conditions:Object.keys(AUTO_CONDITIONS)};
}
function acceptanceDecision(c,title,reason,actor,outcome){const d=recordDecision(c.projectId,c.id,'示例 · '+title,reason);Object.assign(d,{decisionMaker:actor,outcome,example:true});return d;}
function acceptanceFeedback(c,reason,ok=false){c.acceptanceNotice=reason;render();focusAcceptanceOutcome(c.id);return {ok,reason};}
function cardTabKeydown(event){
 const index=CARD_TABS.findIndex(t=>t[0]===view.tab);let next=index;
 if(event.key==='ArrowRight'||event.key==='ArrowDown')next=(index+1)%CARD_TABS.length;
 else if(event.key==='ArrowLeft'||event.key==='ArrowUp')next=(index+CARD_TABS.length-1)%CARD_TABS.length;
 else if(event.key==='Home')next=0;else if(event.key==='End')next=CARD_TABS.length-1;else return;
 event.preventDefault();event.stopPropagation();setCardTab(CARD_TABS[next][0]);
}
function renderCardTabs(c,p){return `<div class="tabs card-tabs" role="tablist" aria-label="卡片详情标签页" onkeydown="cardTabKeydown(event)">${CARD_TABS.map(([tab,label])=>`<button id="tab-${tab}" role="tab" tabindex="${view.tab===tab?0:-1}" aria-selected="${view.tab===tab}" aria-controls="card-tab-panel" onclick="setCardTab(${js(tab)})">${label}</button>`).join('')}</div><div id="card-tab-panel" role="tabpanel" tabindex="0" aria-labelledby="tab-${view.tab}">${view.tab==='dependencies'?renderDependencies(c,p):view.tab==='execution'?renderLiveExecution(c)+renderWorkflow(c)+renderAttempts(c)+renderDispatchExecution(c):view.tab==='acceptance'?renderAcceptance(c):view.tab==='files'?renderFiles(c):view.tab==='records'?renderRecords(c):renderSpec(c)}</div>`;}
function renderRegisteredTests(c){return `<section class="card registered-tests"><h2>登记的测试文件</h2>${c.registeredTests.map(t=>`<p><code>${esc(t.path)}</code> <span class="test-readonly">执行方只读</span> · 来源：${esc(t.source)}${t.modifiedByExecutor?'<strong class="changed">被执行方改过</strong>':''}</p>`).join('')||'<p>无已登记测试文件</p>'}</section>`;}
function specDiff(previous,current){return ['requirements','boundaries','tests'].map(key=>{const before=(previous?.[key]||[]).map(i=>i.text+' · 来源：'+i.source).join('\n'),after=(current[key]||[]).map(i=>i.text+' · 来源：'+i.source).join('\n');return `<h3>${{requirements:'需求',boundaries:'边界',tests:'测试'}[key]}</h3>${before===after?'<p>与上一版相同</p>':`<p>修改前</p><pre>${esc(before||'无历史条目')}</pre><p>修改后</p><pre>${esc(after||'无条目')}</pre>`}`;}).join('');}
function renderSpecHistory(c){return `<section class="card"><h2>规格版本历史与差异</h2>${c.specHistory.map((h,i)=>`<details><summary>规格 v${h.version} · ${esc(h.note)}</summary>${specDiff(c.specHistory[i-1],h)}</details>`).join('')}${c.testEdits.map(e=>`<div class="row"><b>${esc(e.id)}</b><p>修改前：${esc(e.before)}</p><p>修改后：${esc(e.after)}</p><p>理由：${esc(e.reason)} · ${esc(e.judgment)}</p></div>`).join('')}</section>`;}
function renderUpstreamDiff(c){return c.upstreamChanged?`<section class="card upstream-diff"><h2>上游已变 · 差异与结论</h2>${c.dependencies.map(id=>{const u=getCard(id),old=u.outputHistory.find(h=>h.version===c.usedUpstreamVersions[id]),latest=u.outputHistory.at(-1);return `<h3>${esc(u.title)} · v${c.usedUpstreamVersions[id]} → v${u.outputVersion}</h3><p>旧产出：${esc(old?.summary||'未记录')}</p><p>新产出：${esc(latest?.summary||'未记录')}</p>`;}).join('')}<p>项目负责人的结论：${esc(c.upstreamChangeNote||'等待判断，不自动重开')}</p></section>`:'';}
function renderLiveExecution(c){return `<section class="card"><h2>实时输出 · 预设片段</h2>${cardSessions(c).map(s=>`<h3>${esc(dispatchCaption(s))}</h3><div class="session-output">${s.output.map(o=>`<pre>${esc(o.text)}</pre>`).join('')}</div>`).join('')||'<p>尚无执行会话</p>'}</section>`;}
function workflowSteps(a){return a.steps?.length?a.steps:[{id:'dispatch-result-'+a.id,title:'示例 · 核对本次派单产物',status:a.result==='success'?'pass':a.result==='failed'?'fail':'unprocessed',cost:a.cost??0,reason:'示例 · 原记录未保存卡内步骤，以派单结果展示单步检查点',input:'示例 · 本卡规格与工作区',output:a.completionReport||{summary:'尚无完成报告'}}];}
function renderMarketWorkflow(c){const steps=c.attempts[0].steps,branches=steps.filter(s=>s.parallelGroup),join=steps.find(s=>s.id==='market-join');return `<div class="workflow-topology" aria-label="并行检索到汇总"><div class="workflow-branches">${branches.map(s=>`<div class="workflow-branch">∥ ${esc(s.title)} · 代理调用<br>${resultChip(s.status)}</div>`).join('')}</div><p>↓ 并行分支汇合</p><div class="workflow-branch">${esc(join.title)} · 单次模型调用 · ${resultChip(join.status)}</div></div><aside class="workflow-unverifiable"><b>? 无法验证分支 · 单独列出</b>${branches.filter(s=>s.status==='unverifiable').map(s=>`<p>${esc(s.title)}：${esc(s.reason)}</p>`).join('')}</aside>`;}
function renderWorkflow(c){return `<section class="card"><h2>workflow 步骤图</h2>${c.workflowNote?`<p>${esc(c.workflowNote)}</p>`:''}${c.assignmentNote?`<p>${esc(c.assignmentNote)}</p>`:''}${c.id==='a-market'?renderMarketWorkflow(c):''}${c.attempts.map(a=>`<h3>尝试 ${a.number}</h3><ol class="workflow-map">${workflowSteps(a).map(step=>`<li id="workflow-${esc(step.id)}" tabindex="-1" class="workflow-step"><details><summary>${esc(step.title)} · ${RESULTS[step.status]}${step.callType?' · '+esc(step.callType):''}${step.parallelGroup?' · ∥ 并行来源分支':''} · 示例花费 ¥${step.cost??0}</summary><p>${esc(step.reason)}</p><p>输入：${esc(step.input)}</p><h4>原始输出</h4><pre>${esc(JSON.stringify(step.output,null,2))}</pre><button onclick="checkpoint(${js(c.id)},${js(a.id)},${js(step.id)})">回到检查点 · 示例</button></details></li>`).join('')}</ol>`).join('')||'<p>尚无 workflow；不把空步骤视为已通过</p>'}${c.checkpoint?`<p class="changed">${esc(c.checkpoint)}</p>`:''}</section>`;}
function checkpoint(id,dispatchId,stepId){const c=getCard(id),a=c?.attempts.find(a=>a.id===dispatchId),step=a&&workflowSteps(a).find(s=>s.id===stepId);if(!step||['integrated','cancelled'].includes(c.status))return {ok:false};c.checkpoint='示例 · 从「'+step.title+'」重新执行，原始输出和尝试记录保留';c.status='running';simulateArtifactEdit(id,false);acceptanceDecision(c,'回到检查点',c.checkpoint,'你','进行中');render();return {ok:true};}
function verificationGuard(c){
 const v=c.independentVerification;
 if(!v?.sessionId||!v.conclusion)return '拒绝申请：至少需要一次新会话的独立验证结论。';
 if(!v.newSession||c.attempts.some(a=>[a.sessionId,a.sessionKey].includes(v.sessionId)))return '拒绝申请：独立验证必须是新会话，不续接执行方的会话。';
 if(v.commit!==c.currentCommit||v.artifactRevision!==c.artifactRevision)return '拒绝申请：验证后产物又改过，被验证的提交与当前提交不一致，需要重新验证。';
 return '';
}
function makeVerification(c,{actor='项目负责人',agentId='agent-check',method='按规格复核产物与证据',changeModel=true,preset='current',historical=false}={}){
 const sessionId='verification-'+(++db.serial),p=getProject(c.projectId),snapshot=JSON.parse(JSON.stringify({requirements:c.requirements,boundaries:c.boundaries,tests:c.tests,deliverables:c.deliverables}));
 const results=snapshot.tests.map((t,i)=>({...t,result:preset==='pass'?'pass':preset==='fail'&&i===0?'fail':preset==='unverifiable'&&i===0?'unverifiable':t.result,reason:t.result==='unprocessed'?'示例 · 尚未完成该项人工判断':t.result==='unverifiable'?'示例 · 已尝试，但证据不足':'示例 · 预设验证结果',input:'示例 · 本次提交的一次性副本',expected:t.text,actual:'示例 · 按预设结果复核',evidence:'示例 · 产物及附带证据'}));
 const v=deepFreeze({sessionId,newSession:true,agentId,method,changeModel,model:changeModel?'示例 · 不同于执行方的复核模型':'示例 · 与执行方相同模型',commit:c.currentCommit,artifactRevision:c.artifactRevision,baselineRevision:p.baselineRevision,specVersion:c.specVersion,actor,results,snapshot,materials:['本卡规格与测试','本次提交的产物与证据','核心业务逻辑覆盖清单'],omitted:['执行日志','执行方对过程的解释'],copy:'示例 · 按提交导出的无 .git 一次性副本；写入不回收、不合并，结束后删除',conclusion:results.every(t=>t.result==='pass')?'通过':results.some(t=>t.result==='fail')?'失败':'有无法验证或未处理项',coreChecked:true,time:now(),example:true});
 c.verifications.push(v);c.independentVerification=v;
 db.sessions[sessionId]={id:sessionId,projectId:c.projectId,agentId,externalId:null,role:'auxiliary',cardIds:[c.id],currentCardId:c.id,currentDispatchId:null,roundState:'idle',completed:true,spent:0,budget:0,pendingCount:0,unread:false,hasMailbox:false,round:0,pauseReasons:[],output:[{time:v.time,text:'示例 · 新会话独立验证：'+v.conclusion+'；提交 '+v.commit+'；未读取执行日志'}],example:true,verification:v};
 const bad=results.filter(t=>t.result!=='pass');if(bad.length)c.contextPackages.push({dispatchId:'下一轮 · '+sessionId,sent:bad.map(t=>`示例 · 验证未通过 ${t.id}：${t.text}；输入：${t.input}；预期：${t.expected}；实际：${RESULTS[t.result]}；证据：${t.evidence}`),omitted:[{item:'验证方完整的检查清单和执行日志',reason:'只传回异常项，不传过程与完整清单'}],example:true});
 if(!historical)acceptanceDecision(c,'独立验证完成',v.conclusion+'；新会话 '+sessionId+'；提交 '+v.commit,actor,'独立验证已完成');return v;
}
function startIndependentVerification(id,options={}){const c=getCard(id);if(!c)return {ok:false};ensureAcceptance(c);const config={...acceptanceUI,...options};if(!['项目负责人','成员'].includes(config.actor))return acceptanceFeedback(c,'只有项目负责人或成员能拉起独立验证。');const v=makeVerification(c,config);acceptanceFeedback(c,'示例 · 独立验证已完成：'+v.conclusion,true);return {ok:true,verification:v};}
function autoAcceptanceFailures(c){const v=c.independentVerification,checks={verification:v?.conclusion==='通过',deterministic:v?.results.filter(t=>t.type==='deterministic').every(t=>t.result==='pass'),noJudgment:!c.tests.some(t=>t.type==='judgment'),noCore:!c.coreChanges.length,noTestEdits:!c.testEdits.some(t=>t.actor==='项目负责人')};return getProject(c.projectId).autoAcceptanceSettings.conditions.filter(key=>!checks[key]).map(key=>AUTO_CONDITIONS[key]);}
function requestAcceptance(id,actor=acceptanceUI.actor){
 const c=getCard(id);if(!c)return {ok:false};ensureAcceptance(c);
 if(actor!=='项目负责人')return acceptanceFeedback(c,'拒绝申请：只有项目负责人能申请验收。');
 if(c.status!=='running')return acceptanceFeedback(c,'拒绝申请：卡片必须处于进行中。');
 const reason=verificationGuard(c);if(reason)return acceptanceFeedback(c,reason);
 c.status='review';c.requestedCommit=c.currentCommit;c.autoAcceptanceMissing=autoAcceptanceFailures(c);
 acceptanceDecision(c,'申请验收',`被验证的提交 ${c.currentCommit} 就是当前提交；报告交给你。`,actor,'待验收');
 if(getProject(c.projectId).autoAcceptanceSettings.enabled&&!c.autoAcceptanceMissing.length)return finalizeAcceptance(id,'runtime 自动');
 return acceptanceFeedback(c,getProject(c.projectId).autoAcceptanceSettings.enabled?'示例 · 已进入待验收与收件箱；自动验收未满足：'+c.autoAcceptanceMissing.join('、'):'示例 · 已进入待验收与收件箱，等待你验收。',true);
}
function finalizeAcceptance(id,actor='你'){
 const c=getCard(id);if(!c)return {ok:false};ensureAcceptance(c);const p=getProject(c.projectId);
 if(actor!=='你'&&actor!=='runtime 自动')return acceptanceFeedback(c,'验收只能由你，或按你设定的自动条件执行。');
 if(c.status!=='review')return acceptanceFeedback(c,'卡片尚未进入待验收。');
 const reason=verificationGuard(c);if(reason)return acceptanceFeedback(c,reason);
 if(actor==='runtime 自动'&&(!p.autoAcceptanceSettings.enabled||autoAcceptanceFailures(c).length))return acceptanceFeedback(c,'自动验收条件未满足，不能自动验收。');
 c.status='accepted';acceptanceDecision(c,'验收通过',`提交 ${c.currentCommit}；独立验证 ${c.independentVerification.sessionId}`,actor,'已验收');
 const changed=p.baselineRevision!==c.independentVerification.baselineRevision,product=p.type==='产品开发';
 const rerun=product&&changed?{performed:true,scope:'合并结果',result:c.mergePreset||'pass',tests:c.independentVerification.results.filter(t=>t.type==='deterministic').map(t=>({id:t.id,result:c.mergePreset==='fail'?'fail':t.result}))}:null;
 if(rerun&&rerun.tests.some(t=>t.result!=='pass'))rerun.result='fail';
 c.mergeOutcome={baselineChanged:changed,rerun,result:rerun?.result==='fail'?'退回进行中':product?'已合并':'已登记',actor:'runtime',example:true};
 if(rerun?.result==='fail'){
  c.status='running';c.returnReason='基线在验证之后变过，在合并结果上重跑确定性测试不通过；需要修改并重新验证。';c.acceptanceNotice='示例 · 基线在验证之后变过，在合并结果上重跑确定性测试不通过；不合并，退回进行中，需要重新验证。';
  acceptanceDecision(c,'合并失败并退回',c.acceptanceNotice,'runtime','进行中');simulateArtifactEdit(id,false);render();focusAcceptanceOutcome(id);return {ok:false,reason:c.acceptanceNotice};
 }
 c.outputVersion++;c.outputHistory=Object.freeze([...c.outputHistory,deepFreeze({version:c.outputVersion,commit:c.currentCommit,summary:'示例 · '+(product?'runtime 合并':'runtime 登记')+'已验收产出；'+(rerun?'合并结果上重跑确定性测试通过':'基线未变或文档登记'),sources:c.deliverables.slice(),example:true})]);
 c.status='integrated';c.returnReason='';if(product)p.baselineRevision++;
 for(const downstream of projectCards(p))if(downstream.dependencies.includes(id)&&downstream.usedUpstreamVersions[id]<c.outputVersion)downstream.upstreamChanged=true;
 acceptanceDecision(c,product?'合并结果':'登记结果',rerun?'示例 · 基线已变；在合并结果上重跑确定性测试通过，产出 v'+c.outputVersion:'示例 · '+(product?'合并':'登记')+'完成，产出 v'+c.outputVersion,'runtime','已合并 / 已登记');
 return acceptanceFeedback(c,'示例 · 验收通过，runtime '+(product?'已合并':'已登记')+'；产出 v'+c.outputVersion,true);
}
function simulateArtifactEdit(id,update=true){const c=getCard(id);ensureAcceptance(c);if(['integrated','cancelled'].includes(c.status))return {ok:false};c.artifactRevision++;c.currentCommit='示例-提交-'+id+'-'+c.artifactRevision;if(c.status==='accepted'||c.status==='review')c.status='running';if(update)acceptanceFeedback(c,'示例 · 产物已修改，提交 '+c.currentCommit+'；旧验证保留，需要重新验证。',true);return {ok:true};}
function simulateBaselineChange(projectId,result='pass'){const p=getProject(projectId);p.baselineRevision++;for(const c of projectCards(p))c.mergePreset=result;render();return {ok:true};}
function saveAutoAcceptance(id,enabled,conditions,actor='你'){const p=getProject(id);if(actor!=='你'||!p)return {ok:false};conditions=[...new Set(conditions)].filter(key=>Object.hasOwn(AUTO_CONDITIONS,key));if(enabled&&!conditions.length){$('#auto-setting-status').textContent='开启前至少勾选一项自动条件。';return {ok:false};}p.autoAcceptanceSettings={enabled,conditions};const d=recordDecision(id,null,'示例 · 设置自动验收',enabled?'开启：'+conditions.map(k=>AUTO_CONDITIONS[k]).join('、'):'关闭自动验收');d.example=true;render();$('#auto-setting-status').textContent='已保存；申请验收时按条件执行。';return {ok:true};}
function readAutoConditions(){return Object.keys(AUTO_CONDITIONS).filter(k=>$('#auto-'+k).checked);}
function renderAutoAcceptance(p){return `<div class="auto-acceptance"><h2>自动验收条件</h2><p>默认关闭，由你设置；申请验收时 runtime 执行。</p><label class="check"><input id="auto-enabled" type="checkbox" ${p.autoAcceptanceSettings.enabled?'checked':''}>开启自动验收</label>${Object.entries(AUTO_CONDITIONS).map(([key,label])=>`<label class="check"><input id="auto-${key}" type="checkbox" ${p.autoAcceptanceSettings.conditions.includes(key)?'checked':''}>${label}</label>`).join('')}<button onclick="saveAutoAcceptance(${js(p.id)},$('#auto-enabled').checked,readAutoConditions())">保存自动验收设置</button><p id="auto-setting-status" role="status"></p></div>`;}
function renderVerification(v){return `<article class="verification-card"><h3>独立验证的结论：${esc(v.conclusion)} · 示例</h3><p><strong>新会话</strong>，不续接执行方的会话。<button class="verification-link" onclick="openSession(${js(v.sessionId)},event.currentTarget)">验证会话 ${esc(v.sessionId)}</button></p><p>代理：${esc(getAgent(v.agentId)?.name||v.agentId)} · 方法：${esc(v.method)} · 是否换模型：${v.changeModel?'是':'否'} · ${esc(v.model)}</p><p>被验证提交：<code>${esc(v.commit)}</code> · 规格 v${v.specVersion} · ${esc(v.copy)}</p><p>交给验证者：${esc(v.materials.join('、'))}</p><p>没有交给验证者：${esc(v.omitted.join('、'))}</p></article>`;}
function reportTest(t){return `<div class="report-test" data-result="${esc(t.result)}">${resultChip(t.result)} <b>${esc(t.id)}</b> ${esc(t.text)}<p class="src">${esc(t.reason|| (t.result==='unprocessed'?'示例 · 等待处理':t.result==='unverifiable'?'示例 · 已尝试但证据不足':'按记录汇总'))}</p></div>`;}
function renderAcceptance(c){const v=c.independentVerification,results=v?.results||c.tests;return `${renderAcceptanceSummary(c,results,v)}<section class="card acceptance-report"><h2>验收报告</h2><h3>独立验证</h3>${v?renderVerification(v):'<p>尚无独立验证结论；runtime 将拒绝申请。</p>'}<h3>测试结果 · 四种状态</h3><p>${Object.keys(RESULTS).map(resultChip).join(' ')}</p>${results.map(reportTest).join('')}<div class="nonpassing-tests"><h3>非通过项 · 单独列出</h3>${['fail','unverifiable','unprocessed'].map(r=>`<h4>${RESULTS[r]}</h4>${results.filter(t=>t.result===r).map(reportTest).join('')||'<p>无</p>'}`).join('')}</div>${renderHistoricalReview(c)}</section><section class="card core-report"><h2>核心业务逻辑改动</h2><p>执行方标出；验证者核对是否标全：${v?.coreChecked?'示例 · 已核对标全':'尚未独立核对'}</p>${c.coreChanges.map(change=>`<p>${esc(change.text)} · 示例 <button onclick="setCardTab('files')">打开对应 diff</button></p>`).join('')||'<p>示例 · 未标出核心业务逻辑改动</p>'}</section><section class="card leader-report"><h2>项目负责人的说明</h2><p>${esc(c.leaderExplanation||'示例 · 按本卡规格核对交付；未验证事项交给你判断。')}</p><h3>测试与规格修改前后对比</h3>${c.testEdits.map(e=>`<article class="row"><h4>${esc(e.id)} · ${e.example?'示例':'真实记录'}</h4><p>修改前：${esc(e.before)}</p><p>修改后：${esc(e.after)}</p><p>理由：${esc(e.reason)}</p><p>${esc(e.judgment)} · 修改人：${esc(e.actor)}</p><p class="src">${esc(e.source)}</p></article>`).join('')||'<p>没有已记录的测试或规格修改</p>'}${renderReviewRelations(c)}</section><section class="card modified-tests"><h2>被执行方改过的登记测试文件 · 单独标出</h2>${c.registeredTests.filter(t=>t.modifiedByExecutor).map(t=>`<p class="changed">${esc(t.path)} · 示例 · runtime 检测到修改；执行方只读登记文件</p>`).join('')||'<p>没有已记录的执行方修改</p>'}</section><section class="card acceptance-actions"><h2>验收与合并结果</h2>${getProject(c.projectId).autoAcceptanceSettings.enabled&&c.autoAcceptanceMissing?.length?`<p class="changed">自动验收未满足：${esc(c.autoAcceptanceMissing.join('、'))}</p>`:''}${c.mergeOutcome?`<p class="merge-result">示例 · runtime：${esc(c.mergeOutcome.result)}；${c.mergeOutcome.rerun?'基线已变，在合并结果上重跑确定性测试：'+RESULTS[c.mergeOutcome.rerun.result]:'未触发合并结果重跑'}</p>`:''}</section><section class="card acceptance-controls"><h2>独立验证与申请验收 <span class="sample-marker">演示用 · 示例</span></h2><p>当前提交：${esc(c.currentCommit)} · ${esc(acceptanceStateText(c))}</p><p class="src">以下身份切换、代理和预设结果仅供演示，不调用真实服务。</p><div class="form-row"><label>模拟调用身份<select id="acceptance-actor" onchange="acceptanceUI.actor=this.value;render()"><option ${acceptanceUI.actor==='项目负责人'?'selected':''}>项目负责人</option><option ${acceptanceUI.actor==='成员'?'selected':''}>成员</option></select></label><label>验证代理<select id="verification-agent" onchange="acceptanceUI.agentId=this.value">${db.agents.map(a=>`<option value="${esc(a.id)}" ${a.id===acceptanceUI.agentId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>验证方法<select id="verification-method" onchange="acceptanceUI.method=this.value">${['按规格复核产物与证据','对抗型验证','交叉代码审查'].map(m=>`<option ${m===acceptanceUI.method?'selected':''}>${m}</option>`).join('')}</select></label><label class="check"><input id="verification-model" type="checkbox" ${acceptanceUI.changeModel?'checked':''} onchange="acceptanceUI.changeModel=this.checked">换用不同模型</label><label>预设结果<select id="verification-preset" onchange="acceptanceUI.preset=this.value">${[['current','沿用当前四态'],['pass','全部通过'],['fail','首项失败'],['unverifiable','首项无法验证']].map(([key,label])=>`<option value="${key}" ${key===acceptanceUI.preset?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="actions"><button onclick="startIndependentVerification(${js(c.id)})">拉起独立验证 · 新会话</button><button id="request-acceptance" ${acceptanceUI.actor!=='项目负责人'?'disabled':''} onclick="requestAcceptance(${js(c.id)})">申请验收 · 仅项目负责人</button><button onclick="simulateArtifactEdit(${js(c.id)})">模拟产物又改过 · 示例</button></div>${c.verifications.length>1?`<details><summary>独立验证历史 · ${c.verifications.length} 次</summary>${c.verifications.slice(0,-1).map(renderVerification).join('')}</details>`:''}<h3>合并模拟 · 演示用</h3><div class="actions"><button onclick="setCardTab('files')">逐行批注后打回</button><button onclick="simulateBaselineChange(${js(c.projectId)},'pass')">模拟基线变更 · 重跑通过</button><button onclick="simulateBaselineChange(${js(c.projectId)},'fail')">模拟基线变更 · 重跑不通过</button></div></section>`;}
function renderHistoricalReview(c){return c.historicalChecks?`<div class="historical-checks"><h3>真实浏览器检查 · 31/34 → 38/38</h3>${c.historicalChecks.map(h=>`<details open><summary>第 ${h.number} 次 · ${h.score} · 真实记录</summary>${previewReference(h.evidence,'evidence')}<h4>失败项单独列出</h4>${h.failures.map(reportTest).join('')||'<p>无失败项</p>'}</details>`).join('')}</div>`:'';}
function renderReviewRelations(c){const reviews=Object.values(db.cards).filter(r=>r.reviewTarget===c.id);return `${c.reviewTarget?`<p>审查对象：${cardLink(c.reviewTarget)} · 被审查提交 ${esc(c.reviewCommit)} · 真实审查关系，时序映射为示例</p><p>示例 · 实现独立验证 → 浏览器检查完成 → 实现申请验收；审查在合并前完成。</p>`:''}${reviews.map(r=>`<p>以本卡为审查对象：${cardLink(r.id)} · 结论：${esc(r.reviewConclusion)} · ${esc(r.reviewSequence)}</p>`).join('')}`;}
function annotationFiles(c){return c.fileChanges.length?c.fileChanges:[{path:c.deliverables[0]||'产出文档',preview:null,note:'示例 · 产出文档片段',example:true,content:'# '+c.title+'\n示例 · 交付结论与证据待核对\n示例 · 无法验证的项单独说明'}];}
function annotationContent(f){return f.content??artifactPreviews[f.preview]?.content??'示例 · 产出未记录';}
function annotationAnchor(c,path,line){return c.annotations.find(a=>a.path===path&&a.start<=line&&a.end>=line);}
function selectAnnotationLine(id,path,line,extend=false){const c=getCard(id),f=annotationFiles(c).find(f=>f.path===path);if(!f)return;const total=annotationContent(f).split('\n').length;line=Math.max(1,Math.min(total,line));const old=acceptanceUI.selection;acceptanceUI.selection={cardId:id,path,start:extend&&old?.cardId===id&&old.path===path?old.start:line,end:line};render();$('#annotation-line-'+annotationFiles(c).indexOf(f)+'-'+line)?.focus?.({preventScroll:true});}
function annotationLineKeydown(event,id,path,line){
 if(event.key.toLowerCase()==='a'&&!event.ctrlKey&&!event.metaKey&&!event.altKey){event.preventDefault();event.stopPropagation();const sel=acceptanceUI.selection;if(!sel||sel.cardId!==id||sel.path!==path||line<Math.min(sel.start,sel.end)||line>Math.max(sel.start,sel.end))selectAnnotationLine(id,path,line);beginAnnotation(id);}
 else if(['ArrowUp','ArrowDown','Home','End'].includes(event.key)){event.preventDefault();event.stopPropagation();const sel=acceptanceUI.selection;if(!sel||sel.cardId!==id||sel.path!==path||line<Math.min(sel.start,sel.end)||line>Math.max(sel.start,sel.end))acceptanceUI.selection={cardId:id,path,start:line,end:line};const f=annotationFiles(getCard(id)).find(f=>f.path===path),count=annotationContent(f).split('\n').length;selectAnnotationLine(id,path,event.key==='Home'?1:event.key==='End'?count:line+(event.key==='ArrowDown'?1:-1),event.shiftKey);}
}
function beginAnnotation(id){const sel=acceptanceUI.selection;if(!sel||sel.cardId!==id)return {ok:false};const c=getCard(id);acceptanceUI.composer={...sel,start:Math.min(sel.start,sel.end),end:Math.max(sel.start,sel.end),commit:c.currentCommit};render();$('#annotation-text')?.focus?.();return {ok:true};}
function saveAnnotation(id,text=$('#annotation-text')?.value){const c=getCard(id),draft=acceptanceUI.composer;text=String(text||'').trim();if(!draft||draft.cardId!==id||!text)return {ok:false};const f=annotationFiles(c).find(f=>f.path===draft.path);c.annotations.push({id:'annotation-'+(++db.serial),path:draft.path,start:draft.start,end:draft.end,commit:draft.commit,originalLines:annotationContent(f).split('\n').slice(draft.start-1,draft.end),text,resolved:false,sentCount:0,example:true});acceptanceUI.composer=null;render();$('#annotation-line-'+annotationFiles(c).indexOf(f)+'-'+draft.start)?.focus?.({preventScroll:true});return {ok:true};}
function resolveAnnotation(id,annotationId){const c=getCard(id),a=c.annotations.find(a=>a.id===annotationId);if(!a)return {ok:false};a.resolved=!a.resolved;a.resolvedAt=a.resolved?now():null;a.checkedCommit=a.resolved?c.currentCommit:null;render();return {ok:true};}
function sendAnnotations(id,actor='你'){
 const c=getCard(id);if(!c||actor!=='你')return {ok:false};const unresolved=c.annotations.filter(a=>!a.resolved);
 if(!unresolved.length)return acceptanceFeedback(c,'没有未解决的批注，未发送修改请求。');
 if(!['running','review','accepted'].includes(c.status))return acceptanceFeedback(c,'只能向进行中、待验收或已验收卡片发回批注。');
 if(!currentOwnerSession(c))return acceptanceFeedback(c,'没有负责成员，暂时无法发回。');
 const request={id:'revision-request-'+(++db.serial),annotationIds:unresolved.map(a=>a.id),commit:c.currentCommit,time:now(),recipient:currentOwnerSession(c).id,example:true};c.modificationRequests.push(request);unresolved.forEach(a=>a.sentCount++);c.status='running';c.returnReason='示例 · 你逐行批注后打回，负责成员需要修改并重新验证。';
 const text='示例 · 一次修改请求 '+request.id+'\n'+unresolved.map(a=>`${a.path} 原行 ${a.start}–${a.end}（${a.commit}）\n${a.text}`).join('\n\n');
 queueMail(c.projectId,'question',getProject(c.projectId).leaderSessionId,{kind:'card-owner',id:c.id},[id],text,{requestId:request.id});
 c.contextPackages.push({dispatchId:'下一轮 · '+request.id,sent:unresolved.map(a=>'示例 · 原行 '+a.start+'–'+a.end+'：'+a.text),omitted:[{item:'已解决批注',reason:'已由你核对，无需再修改'}],example:true});
 acceptanceDecision(c,'逐行批注后打回',text,'你','进行中');return acceptanceFeedback(c,'示例 · '+unresolved.length+' 条未解决批注合成一次修改请求，已发给负责成员；卡片回到进行中。',true);
}
function simulateAnnotationRevision(id){const c=getCard(id);if(!c.modificationRequests.length)return acceptanceFeedback(c,'请先一次性发回批注。');c.revisedFileContents||={};for(const f of annotationFiles(c)){const lines=(c.revisedFileContents[f.path]||annotationContent(f)).split('\n');for(const a of c.annotations.filter(a=>!a.resolved&&a.path===f.path))for(let i=a.start-1;i<a.end;i++)lines[i]=(lines[i]||'')+' · 示例：成员已修正';c.revisedFileContents[f.path]=lines.join('\n');}simulateArtifactEdit(id,false);c.annotationRevisionNote='示例 · 成员已按批注提交修改；原行锚点与原文保留，请逐条核对后标为已解决。';render();return {ok:true};}
function renderAnnotationMarkdown(text){return renderMarkdown(text).replace(/\*\*([^*<>]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`<>]+)`/g,'<code>$1</code>');}
function renderAnnotationBubble(c,a){return `<aside class="annotation-bubble" data-annotation-id="${esc(a.id)}"><b>原行 ${a.start}${a.end!==a.start?'–'+a.end:''} · 示例</b><p>锚定提交：${esc(a.commit)}</p><details><summary>原文</summary><pre>${esc(a.originalLines.join('\n'))}</pre></details><div class="annotation-markdown">${renderAnnotationMarkdown(a.text)}</div><span class="${a.resolved?'annotation-resolved':'annotation-open'}">${a.resolved?'已解决':'待核对'}</span>${a.resolved?`<p>核对提交：${esc(a.checkedCommit||'示例 · 第 2 次修改后')}</p>`:''}<button onclick="resolveAnnotation(${js(c.id)},${js(a.id)})">${a.resolved?'重新打开':'核对并标为已解决'}</button></aside>`;}
function renderAnnotatedFile(c,f){if(!f)return '';const selection=acceptanceUI.selection,index=annotationFiles(c).findIndex(file=>file.path===f.path);return `<div class="annotated-file" data-file-path="${esc(f.path)}"><p class="src">点击行选中；Shift+点击选连续行。键盘：方向键移动、Shift+方向键扩选、A 写批注。</p><div class="annotation-lines">${(c.revisedFileContents?.[f.path]||annotationContent(f)).split('\n').map((line,i)=>{const n=i+1,selected=selection?.cardId===c.id&&selection.path===f.path&&n>=Math.min(selection.start,selection.end)&&n<=Math.max(selection.start,selection.end),kind=line.startsWith('+')?'preview-diff-add':line.startsWith('-')?'preview-diff-delete':'';return `<div class="annotation-row"><button id="annotation-line-${index}-${n}" class="annotation-line ${kind} ${selected?'annotation-selected':''}" data-line="${n}" aria-pressed="${Boolean(selected)}" onclick="selectAnnotationLine(${js(c.id)},${js(f.path)},${n},event.shiftKey)" onkeydown="annotationLineKeydown(event,${js(c.id)},${js(f.path)},${n})"><span class="annotation-number">${n}</span><code>${esc(line||' ')}</code>${annotationAnchor(c,f.path,n)?'<span class="annotation-marker">批注</span>':''}</button>${c.annotations.filter(a=>a.path===f.path&&a.start===n).map(a=>renderAnnotationBubble(c,a)).join('')}</div>`;}).join('')}</div></div>`;}
function renderAnnotationComposer(c){const draft=acceptanceUI.composer;return `<section class="card annotation-controls"><h2>逐行批注后打回 <span class="sample-marker">示例</span></h2><p>批注钉在原提交的原行上；未解决的批注在下次发回时自动带上。</p><button onclick="beginAnnotation(${js(c.id)})">为选中行写批注</button>${draft?.cardId===c.id?`<div class="annotation-editor"><label>${esc(draft.path)} · 原行 ${draft.start}–${draft.end}<textarea id="annotation-text" placeholder="Markdown 批注" onkeydown="if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();saveAnnotation(${js(c.id)});}else if(event.key==='Escape'){event.preventDefault();event.stopPropagation();acceptanceUI.composer=null;render();}"></textarea></label><button onclick="saveAnnotation(${js(c.id)})">保存批注（Ctrl / ⌘ + Enter）</button></div>`:''}<div class="actions"><button onclick="sendAnnotations(${js(c.id)})">一次性发回 · ${c.annotations.filter(a=>!a.resolved).length} 条未解决</button><button onclick="simulateAnnotationRevision(${js(c.id)})">模拟成员修改 · 示例</button></div><p>${esc(c.annotationRevisionNote||'')}</p><p id="annotation-outcome" class="acceptance-notice" role="status" tabindex="-1">${esc(c.acceptanceNotice)}</p><details><summary>修改请求历史 · ${c.modificationRequests.length} 次</summary>${c.modificationRequests.map(r=>`<p>示例 · ${esc(r.id)} · ${r.annotationIds.length} 条批注 · 负责成员 ${esc(r.recipient)} · ${esc(r.time)}</p>`).join('')}</details></section>`;}
