function toggleStatusEditor(id,open=true){statusEditorState.cardId=open?id:null;render();$(open?'#status-line-input':'#status-line-edit')?.focus?.();}
function renderCompactStatus(c){return `<div class="card-status-summary"><span class="src">状态行</span>${renderStatusLine(c)}<button id="status-line-edit" aria-expanded="${statusEditorState.cardId===c.id}" onclick="toggleStatusEditor(${js(c.id)},${statusEditorState.cardId!==c.id})">编辑</button></div>`;}
function renderStatusHistory(c){return `<details><summary>状态行历史 · ${(c.statusLineHistory||[]).length} 条</summary>${(c.statusLineHistory||[]).slice().reverse().map(h=>`<div class="row"><p>${esc(h.text)}</p><div class="src">${esc(h.time)} · ${esc(h.actor)}</div></div>`).join('')}</details>`;}
function acceptanceStateText(c){
 const product=getProject(c.projectId).type==='产品开发';
 if(c.status==='running')return c.returnReason?'本卡已退回进行中。退回原因：'+c.returnReason:'本卡正在进行中；独立验证完成不会自动申请验收，仍由项目负责人申请。';
 if(c.status==='review')return '本卡待验收，已进入收件箱，等待你验收或按你设置的自动条件验收。';
 if(c.status==='accepted')return '本卡已验收，等待 runtime '+(product?'合并':'登记')+'。';
 if(c.status==='integrated')return '本卡'+(product?'已合并':'已登记')+'，产出 v'+c.outputVersion+'。';
 return '本卡'+STATUS[c.status]+'；当前不能申请验收。';
}
function focusAcceptanceOutcome(id){
 if(view.page!=='card'||view.id!==id||sessionPanel.id)return;
 const selector=view.tab==='acceptance'?'#acceptance-outcome':view.tab==='files'?'#annotation-outcome':'#tab-'+view.tab;
 $('#main').querySelector(selector)?.focus?.();
}
function renderAcceptanceSummary(c,results,v){
 const counts=Object.keys(RESULTS).map(key=>({key,label:RESULTS[key],count:results.filter(t=>t.result===key).length}));
 const concerns=[...results.filter(t=>t.result!=='pass').map(t=>RESULTS[t.result]+'：'+t.text),...c.coreChanges.map(t=>'核心业务逻辑改动：'+t.text),...c.testEdits.filter(t=>t.actor==='项目负责人').map(t=>'项目负责人改过的测试：'+t.id),...c.registeredTests.filter(t=>t.modifiedByExecutor).map(t=>'执行方改过登记测试：'+t.path)];
 return `<section class="card acceptance-summary" aria-labelledby="acceptance-summary-heading"><h2 id="acceptance-summary-heading">验收报告摘要</h2><p class="acceptance-state">${esc(acceptanceStateText(c))}</p><div class="result-counts">${counts.map(t=>`<span class="result-count s-${{pass:'integrated',fail:'cancelled',unverifiable:'paused',unprocessed:'draft'}[t.key]}" data-result="${t.key}" data-count="${t.count}">${t.label} ${t.count}</span>`).join('')}</div><p>独立验证结论：<strong>${esc(v?.conclusion||'尚无结论')}</strong></p><h3>需要你重点看的项</h3>${concerns.length?`<ul class="acceptance-priorities">${concerns.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p>当前报告没有标出需重点处理的项。</p>'}${c.status==='review'?`<div class="actions"><button id="summary-accept" class="primary ok" onclick="acceptCard(${js(c.id)})">验收 · runtime 合并或登记</button><button id="summary-return" onclick="setCardTab('files')">打回 · 逐行批注</button></div>`:''}<p id="acceptance-outcome" class="acceptance-notice" role="status" tabindex="-1">${esc(c.acceptanceNotice||acceptanceStateText(c))}</p></section>`;
}

// 第 5 批：回放是历史投影；答疑读取记录，采纳草稿由用户进入正常流程。
const replayState={indices:{},playing:false,token:0,timer:null};
const libraryState={editing:null,openGroups:new Set(['卡片组合'])};
const askState={open:false,context:null,origin:null,activeId:null,draft:'',error:''};
function replayEvents(p){return db.replayEvents[p.id]||[];}
function replayIndex(p){return Math.max(0,Math.min(replayEvents(p).length-1,replayState.indices[p.id]||0));}
function stopReplay(){replayState.playing=false;replayState.token++;clearTimeout(replayState.timer);}
function seekReplay(index,manual=true){const p=getProject(view.id)||getProject(getCard(view.id)?.projectId);if(!p)return;if(manual)stopReplay();replayState.indices[p.id]=Math.max(0,Math.min(replayEvents(p).length-1,Number(index)||0));if(view.page==='project'&&view.board==='replay'&&$('#main').querySelector('#replay-timeline'))updateReplayView(p);else render();}
function stepReplay(delta){seekReplay(replayIndex(getProject(view.id))+delta);}
function playReplay(){const p=getProject(view.id);if(!p||!replayEvents(p).length)return;if(replayState.playing){stopReplay();updateReplayView(p);return;}if(replayIndex(p)===replayEvents(p).length-1)replayState.indices[p.id]=0;replayState.playing=true;const token=++replayState.token;updateReplayView(p);function tick(){if(!replayState.playing||token!==replayState.token||view.page!=='project'||view.id!==p.id||view.board!=='replay')return;replayState.indices[p.id]=replayIndex(p)+1;if(replayIndex(p)>=replayEvents(p).length-1)stopReplay();updateReplayView(p);if(replayState.playing)replayState.timer=setTimeout(tick,1600);}replayState.timer=setTimeout(tick,1600);}

function replaySnapshot(p,index=replayIndex(p)){
 const snapshots={},events=replayEvents(p);for(const e of events.slice(0,index+1))for(const change of e.changes){const original=getCard(change.cardId);snapshots[change.cardId]={...original,dependencies:original.dependencies.slice(),status:change.status,outputVersion:0,specVersion:1,statusLine:'历史快照 · 示例映射',tests:[],historySnapshot:true,unread:false,upstreamChanged:false,usedUpstreamVersions:{},...snapshots[change.cardId],...change,status:change.status};}
 const current=events[index];for(const c of Object.values(snapshots)){const change=current?.changes.find(r=>r.cardId===c.id);c.replayMark=change?change.kind==='add'?'＋ 新增':change.kind==='split'?'↳ 拆出子卡':'△ 刚变化':'';}
 const f=boardState.filters,cards=Object.values(snapshots).filter(c=>(!f.group||c.groups.includes(f.group))&&(!f.status||c.status===f.status)&&(!f.owner||db.members[c.memberId]?.agentId===f.owner)&&(!f.mine||inboxItems(p.id).some(i=>i.cardIds.includes(c.id)))&&!parentHidden(c));
 const ids=new Set(cards.map(c=>c.id)),edges=cards.flatMap(c=>c.dependencies.filter(id=>ids.has(id)).map(from=>({from,to:c.id})));for(const c of cards)if(c.parentId&&ids.has(c.parentId))edges.push({from:c.parentId,to:c.id,split:true});
 return {...p,cardIds:cards.map(c=>c.id),edges,cards:snapshots};
}
function replayGraph(p,options={}){const graph=replaySnapshot(p);return renderFlowSVG(graph,{...options,cards:graph.cards,readOnly:true});}
function replayEventHeading(p){const e=replayEvents(p)[replayIndex(p)];return `<b>${esc(e.title)}</b> · ${esc(e.time)}`;}
function selectReplayEvent(index,trigger){
 seekReplay(index);
 $('#main').querySelector('.replay-explanation').scrollTop=0;
 trigger?.focus({preventScroll:true});
}
function replayEventAnnouncement(p){const index=replayIndex(p),e=replayEvents(p)[index];return `第 ${index+1} / ${replayEvents(p).length} 步：${e.title}。${e.changes.map(c=>`${c.kind==='add'?'新增':c.kind==='split'?'拆出子卡':'状态变化'}：${getCard(c.cardId).title}，${STATUS[c.status]}`).join('；')}。项目负责人的组织理由：${e.reason}`;}
function replayEventDetails(p){const e=replayEvents(p)[replayIndex(p)],snapshot=replaySnapshot(p);return `<p class="organization-reason">项目负责人的组织理由：${esc(e.reason)}</p>${e.commit?`<p class="src">提交 <code>${esc(e.commit)}</code><br>${esc(e.subject)}<br><span class="replay-inferred">示例 · 推断的卡片映射</span></p>`:''}<p>关键消息：${esc(e.message)}</p><ul>${e.changes.map(c=>`<li>${c.kind==='add'?'＋ 新增':c.kind==='split'?'↳ 拆子卡':'△ 状态 / 产出变化'} · ${cardLink(c.cardId)} · ${STATUS[c.status]}${c.parentId?' · 父卡：'+getCard(c.parentId).title:''}${c.outputVersion?' · 产出 v'+c.outputVersion:''}</li>`).join('')}</ul><div class="replay-legend"><span class="replay-new">＋ 新增卡</span><span class="replay-changed">△ 刚变化</span><span class="replay-split">↳ 拆出的子卡（虚线父子关系）</span><span>历史集合 ${snapshot.cardIds.length} 张</span></div>`;}
function updateReplayView(p){
 const main=$('#main'),range=main.querySelector('#replay-timeline'),canvas=main.querySelector('.replay-graph')?.querySelector('.flow-canvas');if(!range||!canvas)return;
 const index=replayIndex(p),e=replayEvents(p)[index];range.value=String(index);range.setAttribute('value',String(index));range.setAttribute('aria-valuetext',e.title);main.querySelector('#replay-counter').innerHTML=`时间轴 · 第 ${index+1} / ${replayEvents(p).length} 步`;
 for(const [id,disabled] of [['replay-back',index===0],['replay-next',index===replayEvents(p).length-1]]){const b=main.querySelector('#'+id);b.disabled=disabled;if(disabled)b.setAttribute('disabled','');else b.removeAttribute('disabled');}
 const play=main.querySelector('#replay-play');play.setAttribute('aria-pressed',String(replayState.playing));play.innerHTML=replayState.playing?'暂停播放':'自动播放';
 main.querySelector('#replay-current-heading').innerHTML=replayEventHeading(p);main.querySelector('#replay-current-details').innerHTML=replayEventDetails(p);
 main.querySelector('#replay-announcement').textContent=replayEventAnnouncement(p);
 const scroll={left:canvas.scrollLeft||0,top:canvas.scrollTop||0};canvas.innerHTML=replayGraph(p,flowViewport(canvas));canvas.scrollLeft=scroll.left;canvas.scrollTop=scroll.top;
 for(const button of main.querySelectorAll('.replay-directory'))button.setAttribute('aria-current',Number(button.dataset.replayIndex)===index?'step':'false');
}
function renderReplay(p){
 const events=replayEvents(p),index=replayIndex(p),e=events[index];if(!e)return '<section class="card">这个项目尚无回放记录。</section>';
 return `<div class="replay-workspace"><section class="card replay-controls"><header class="replay-header"><h2>看板回放 ${p.example?'· 示例':'· 真实提交历史'}</h2><label><span id="replay-counter">时间轴 · 第 ${index+1} / ${events.length} 步</span><input id="replay-timeline" class="replay-timeline" type="range" min="0" max="${events.length-1}" step="1" value="${index}" aria-valuetext="${esc(e.title)}" onpointerdown="stopReplay();updateReplayView(getProject(view.id))" oninput="seekReplay(this.value)"></label><div class="actions"><button id="replay-back" ${index===0?'disabled':''} onclick="stepReplay(-1)">← 上一步</button><button id="replay-play" aria-pressed="${replayState.playing}" onclick="playReplay()">${replayState.playing?'暂停播放':'自动播放'}</button><button id="replay-next" ${index===events.length-1?'disabled':''} onclick="stepReplay(1)">下一步 →</button></div><p id="replay-current-heading" class="replay-event">${replayEventHeading(p)}</p><span id="replay-announcement" class="visually-hidden" role="status" aria-live="polite" aria-atomic="true">${esc(replayEventAnnouncement(p))}</span></header><div class="replay-explanation" tabindex="0" aria-label="当前回放事件说明"><div id="replay-current-details">${replayEventDetails(p)}</div><details><summary>回放来源与筛选说明</summary><p class="src">${p.example?'全部为示例。':'提交时间与说明来自本仓库；卡片出现、状态和组织理由是示例推断，不是实际派单时间。三张缺陷示例卡没有历史提交，仅在当前看板展示。'} 筛选按当时状态匹配；“我要处理的”按当前收件箱匹配。点击历史卡片查看当前详情。</p></details></div><details class="replay-directory-panel"><summary>事件目录</summary><div class="replay-directory-scroll" role="region" aria-label="回放事件目录">${events.map((e,n)=>`<button class="replay-directory" data-replay-index="${n}" aria-current="${index===n?'step':'false'}" onclick="selectReplayEvent(${n},event.currentTarget)">${n+1}. ${esc(e.title)}</button>`).join('')}</div></details></section><div class="flow-diagram replay-graph" data-project-id="${esc(p.id)}" data-replay="true"><p class="flow-scroll-hint">历史依赖图 · 图内滚动，时间轴和事件保留在旁边 / 上方</p><div class="flow-canvas" tabindex="0" aria-label="历史依赖图滚动区">${replayGraph(p,flowViewport())}</div></div></div>`;
}

function askContextProject(context){return getProject(context?.projectId)||getProject(getCard(context?.id)?.projectId)||getProject(context?.id)||getProject('project-b');}
function contextCaption(context){return context?.kind==='card'?'卡片 · '+getCard(context.id)?.title:context?.kind==='message'?'消息 · '+(byId(db.messages,context.id)?.content||context.id):context?.kind==='inbox'?'收件箱 · 全部项目':(context?.kind==='board'?'看板 · ':context?.kind==='timeline'?'消息时间线 · ':'项目 · ')+askContextProject(context).name;}
function askButton(kind,id,projectId,label='问一下'){return `<button class="ask-entry" data-ask-kind="${kind}" data-ask-id="${esc(id||'')}" onclick="openAsk({kind:${js(kind)},id:${js(id||null)},projectId:${js(projectId||null)}},event.currentTarget)">${label}</button>`;}
function openAsk(context,trigger){stopReplay();askState.context={...context};askState.origin=focusDescriptor(trigger||document.activeElement);askState.open=true;askState.activeId=null;askState.draft='';askState.error='';render();$('#ask-input')?.focus();}
function closeAsk(restore=true){askState.open=false;askState.error='';render();if(restore)restoreDescriptor(askState.origin,'#conversation-toggle',true);}
function askKeydown(event){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();closeAsk();return;}if(event.key==='Tab'){const items=[...$('#main').querySelector('.ask-panel').querySelectorAll('button'),...$('#main').querySelector('.ask-panel').querySelectorAll('textarea')].filter(n=>!n.disabled&&n.getAttribute('disabled')==null),first=items[0],last=items.at(-1);const ordered=[...$('#main').querySelector('.ask-panel').querySelectorAll('*')].filter(n=>items.includes(n));if(event.shiftKey&&document.activeElement===ordered[0]){event.preventDefault();ordered.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===ordered.at(-1)){event.preventDefault();ordered[0]?.focus();}}}
function askPreset(question,p){
 const normalized=question.replace(/\s+/g,'').replace(/[？?。！!]+$/,'');
 const evidence=(label,line)=>({kind:'log',label:'尝试 #1 · 步骤 browser-1-verify · '+label,path:'evidence/002/assertions.txt:'+line});
 if(p.id==='project-b'&&['浏览器检查第1次为什么只有31/34','31/34'].includes(normalized))return {cost:.18,conclusions:[
 {status:'confirmed',layer:'测试',text:'已确认：34 条里 3 条失败。S10 是深色按钮文字 2.16:1（要求 ≥4.5:1）；S11 正文列只有 59.3px、短标题 3 行；S03 把 t3 的修正记录要求错放到 t2，应修正检查对象。',evidence:[evidence('S10 · 日志 31 行',31),evidence('S11 · 日志 33 行',33),evidence('S03 · 日志 10–11 行',10),{kind:'attempt',label:'浏览器检查 · 尝试 #1',cardId:'b-browser',number:1},{kind:'step',label:'步骤 browser-1-verify',cardId:'b-browser',stepId:'browser-1-verify'}]},
 {status:'inferred',layer:'上下文包',text:'推测：实现方首轮可能没有充分检查窄屏可读性与深色按钮。缺少当时完整上下文包与自测输出；不能确认是漏测还是自测环境差异。',evidence:[evidence('S11 实际结果',33),{kind:'attempt',label:'实现 · 尝试 #1（历史摘要，完整自测未记录）',cardId:'b-implement',number:1}]},
 {status:'unknown',layer:'环境 / 执行者能力',text:'无法确定：没有当时环境快照与完整会话权限日志，无法归因于执行者或环境。怎么查：核对一次性副本、视口配置及会话原始输出；历史缺失记录不能补造。',evidence:[{kind:'step',label:'浏览器检查步骤 #1 的来源记录；环境快照缺失',cardId:'b-browser',stepId:'browser-1-enumerate'}]}
 ],suggestion:{kind:'return',cardId:'b-implement',status:'draft',text:'示例 · 起草退回「实现」：修复 S10 深色对比度与 S11 窄屏可读性；S03 交给出题会话纠正测试，复检后再申请验收。历史已完成返工；采纳会在当前 Demo 再次退回。'}};
 if(p.id==='project-a'&&['市场调研为什么无法验证','市场调研为什么暂停','市场调研是谁指派的'].includes(normalized))return {cost:.12,conclusions:[
 {status:'confirmed',layer:'调度决定',text:'已确认（示例）：市场调研命中你的预设指派规则，runtime 直接拉起；当前因预算达到上限暂停。',evidence:[{kind:'decision',label:'runtime 指派决策',decisionId:'a-runtime-assignment'},{kind:'attempt',label:'市场调研 · 尝试 #1',cardId:'a-market',number:1}]},
 {status:'inferred',layer:'上下文包',text:'推测（示例）：报价来源不足。缺少可交叉核对的最新证据，补一手来源后再判断。',evidence:[{kind:'step',label:'market-pricing · 无法验证分支',cardId:'a-market',stepId:'market-pricing'}]},
 {status:'unknown',layer:'需求理解',text:'无法确定（示例）：缺证据时不能保证市场结论；先追加预算与资料，再完成汇总。',evidence:[{kind:'step',label:'market-join · 汇总未处理',cardId:'a-market',stepId:'market-join'}]}
 ],suggestion:null};
 return {cost:0,conclusions:[],suggestion:null,unsupported:true};
}
function submitAsk(question=$('#ask-input')?.value){question=String(question||'').trim();if(!question)return {ok:false};const p=askContextProject(askState.context),answer=askPreset(question,p);if(p.answerBudget.spent+answer.cost>p.answerBudget.limit){askState.error='答疑预算不足，请在项目设置调整后再问。';render();return {ok:false};}
 const record={id:'ask-'+(++db.serial),projectId:p.id,context:{...askState.context},question,time:now(),externalSessionId:null,sessionNote:'示例 · 每个问题一个新答疑会话，真实 ID 未记录',example:true,...answer};db.askHistory.push(record);p.answerBudget.spent=Math.round((p.answerBudget.spent+answer.cost)*100)/100;askState.activeId=record.id;askState.draft=question;askState.error='';render();$('#ask-answer')?.focus();return {ok:true,id:record.id};}
function viewAskHistory(id){const q=byId(db.askHistory,id);if(!q)return;askState.context={...q.context};askState.activeId=id;askState.draft=q.question;render();$('#ask-answer')?.focus();}
function askEvidence(recordId,index,evidenceIndex,trigger){const q=byId(db.askHistory,recordId),e=q?.conclusions[index]?.evidence[evidenceIndex];if(!e)return;if(e.kind==='log')return openArtifactPreview(e.path,trigger);askState.open=false;if(e.kind==='decision')return decisionJump(e.decisionId);go('card',e.cardId);setCardTab('execution');const selector=e.kind==='step'?'#workflow-'+e.stepId:'#attempt-'+e.cardId+'-'+e.number;const target=$('#main').querySelector('.card-detail')?.querySelector(selector);for(let n=target;n;n=n.parentElement)if(n.tagName==='DETAILS')n.open=true;target?.focus?.();target?.scrollIntoView?.({block:'center',inline:'nearest'});return {ok:Boolean(target),target:selector};}
function adoptAskSuggestion(id){const q=byId(db.askHistory,id),draft=q?.suggestion,c=getCard(draft?.cardId);if(!draft||draft.status!=='draft'||!c)return {ok:false};if(!['running','review','accepted','integrated'].includes(c.status)){askState.error='当前卡片状态不适合退回，请先查看卡片。';render();return {ok:false};}
 draft.status='adopted';c.status='running';c.independentVerification=null;c.returnReason=draft.text;c.acceptanceNotice='你采纳了答疑退回草稿；卡片回到进行中，须重新验证并申请验收。';c.handoffs.push({time:now(),text:draft.text,example:true});c.contextPackages.push({dispatchId:'示例 · 下一次派单',sent:[draft.text,'真实依据：evidence/002/assertions.txt:31、33'],omitted:[{item:'S03 作为实现缺陷',reason:'原检查要求写错，交出题会话修正'}],example:true});
 const p=getProject(c.projectId),affected=[...flowReachable(c.id,projectEdges(p))].filter(id=>id!==c.id);for(const id of affected){getCard(id).upstreamChanged=true;getCard(id).upstreamChangeNote='示例 · 你采纳退回实现，项目负责人须重新判断受影响范围并安排重新验证。';}
 const d=recordDecision(q.projectId,c.id,'采纳答疑建议 · 退回「'+c.title+'」',draft.text);d.adoptedAsIs=true;d.askId=q.id;d.example=true;draft.decisionId=d.id;queueMail(c.projectId,'question',p.leaderSessionId,{kind:'card-owner',id:c.id},[c.id],draft.text,{requestId:q.id});render();$('#ask-answer')?.focus();return {ok:true,decisionId:d.id};}
function ignoreAskSuggestion(id){const q=byId(db.askHistory,id);if(q?.suggestion?.status!=='draft')return {ok:false};q.suggestion.status='ignored';render();return {ok:true};}
function renderAsk(){const p=askContextProject(askState.context),q=byId(db.askHistory,askState.activeId),labels={confirmed:'✓ 已确认',inferred:'△ 推测',unknown:'? 无法确定'};return `<div class="ask-backdrop" onclick="if(event.target===this)closeAsk()"><section class="ask-panel" role="dialog" aria-modal="true" aria-labelledby="ask-title" onkeydown="askKeydown(event)"><header class="panel-header"><h2 id="ask-title">问一下 · 答疑负责人</h2><button id="ask-close" onclick="closeAsk()">关闭</button></header><p id="ask-context">当前对象：${esc(contextCaption(askState.context))}</p><p class="src">示例回答 · 原型不接模型。只读记录；建议动作只起草。归因层：需求理解、测试、上下文包、执行者能力、环境、调度决定。每个问题一条记录、新答疑会话；历史会话 ID 未记录。</p><p>答疑预算 ¥${p.answerBudget.spent.toFixed(2)} / ¥${p.answerBudget.limit} · 示例</p><div class="actions">${p.id==='project-b'?'<button id="ask-demo" onclick="submitAsk(\'浏览器检查第 1 次为什么只有 31/34\')">浏览器检查第 1 次为什么只有 31/34</button>':'<button id="ask-demo" onclick="submitAsk(\'市场调研为什么无法验证\')">市场调研为什么无法验证</button>'}</div><label>你的问题<textarea id="ask-input" oninput="askState.draft=this.value">${esc(askState.draft)}</textarea></label><button onclick="submitAsk()">提交问题</button><p role="status">${esc(askState.error)}</p>${q?`<section id="ask-answer" tabindex="-1" aria-label="答疑回答"><h3>${esc(q.question)}</h3><p class="src">${esc(q.sessionNote)} · 花费 ¥${q.cost.toFixed(2)} · 示例</p>${q.unsupported?'<p>示例 · 原型只回答预设问题。请使用上方预设问题；本条已保留，花费为 ¥0。</p>':q.conclusions.map((c,n)=>`<article class="ask-conclusion ask-${c.status}"><b>${labels[c.status]}</b><p>问题所在层：${esc(c.layer)}</p><p>${esc(c.text)}</p><p>依据：${c.evidence.map((e,i)=>`<button data-ask-evidence="${esc(e.kind)}" onclick="askEvidence(${js(q.id)},${n},${i},event.currentTarget)">${esc(e.label)}</button>`).join(' ')}</p></article>`).join('')}${q.suggestion?`<section class="card ask-suggestion"><h3>建议草稿 · ${esc(({draft:'尚未执行',adopted:'已采纳，进入正常流程',ignored:'已忽略'})[q.suggestion.status])}</h3><p>${esc(q.suggestion.text)}</p>${q.suggestion.status==='draft'?`<button id="ask-adopt" class="primary" onclick="adoptAskSuggestion(${js(q.id)})">一键采纳 · 退回实现</button> <button id="ask-ignore" onclick="ignoreAskSuggestion(${js(q.id)})">忽略</button>`:q.suggestion.decisionId?`<button onclick="askState.open=false;decisionJump(${js(q.suggestion.decisionId)})">查看采纳决策</button>`:''}</section>`:''}</section>`:''}<section class="card ask-history"><h3>问一下的历史 · ${db.askHistory.filter(q=>q.projectId===p.id).length} 条</h3>${db.askHistory.filter(q=>q.projectId===p.id).slice().reverse().map(q=>`<div class="row"><button onclick="viewAskHistory(${js(q.id)})">${esc(q.question)}</button><p class="src">${esc(contextCaption(q.context))} · ${esc(q.time)} · ¥${q.cost.toFixed(2)}</p></div>`).join('')||'<p>还没有问题</p>'}</section></section></div>`;}
function enabledPlaybooks(p){return db.playbookLibrary.filter(t=>p.enabledPlaybookIds?.includes(t.id));}
function updateLeaderPlaybooks(p){p.leaderContext={handbook:'HANDBOOK.md 全部',playbooks:enabledPlaybooks(p).map(t=>({id:t.id,title:t.title,content:t.content})),note:'示例 · 启用的打法在下次唤醒 / 派单时放进项目负责人的上下文，只作参考。'};p.playbooks=enabledPlaybooks(p).map(t=>t.title);}
function togglePlaybook(id){const p=getProject(view.id)||getProject('project-b'),t=byId(db.playbookLibrary,id);if(!t)return;p.enabledPlaybookIds||=[];const enabled=!p.enabledPlaybookIds.includes(id);p.enabledPlaybookIds=enabled?[...p.enabledPlaybookIds,id]:p.enabledPlaybookIds.filter(x=>x!==id);updateLeaderPlaybooks(p);recordDecision(p.id,null,(enabled?'启用':'停用')+'打法：'+t.title,'你调整项目负责人的参考上下文。');render();}
function editPlaybook(id){libraryState.editing=id;const entry=byId(db.playbookLibrary,id);if(entry)libraryState.openGroups.add(entry.kind);render();$('#play-title')?.focus();}
function savePlaybook(id,title=$('#play-title')?.value,content=$('#play-content')?.value){const t=byId(db.playbookLibrary,id);if(!t||!String(title||'').trim()||!String(content||'').trim())return {ok:false};const before=t.content;t.title=title.trim();t.content=content.trim();t.edited=true;db.projects.forEach(updateLeaderPlaybooks);recordDecision(getProject(view.id)?.id,null,'编辑打法：'+t.title,'修改前：'+before+'；修改后：'+t.content);libraryState.editing=null;render();return {ok:true};}
function reviewPlaybook(id,accept){const q=byId(db.playbookProposals,id);if(!q||q.status!=='pending')return {ok:false};q.status=accept?'approved':'rejected';if(accept)db.playbookLibrary.push({id:'play-'+(++db.serial),title:q.title,kind:q.kind,content:q.content,source:'示例 · 新打法提议',stats:{references:0,firstPass:0,total:0,cost:0,returns:0,example:true}});const d=recordDecision(getProject(view.id)?.id,null,(accept?'通过':'驳回')+'新打法：'+q.title,q.reason);q.decisionId=d.id;render();return {ok:true};}
function libraryProjectPicker(page,p){return `<label>当前项目<select id="library-project" onchange="go(${js(page)},this.value)">${db.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`;}
function playbookGroupToggle(element,kind){element.open?libraryState.openGroups.add(kind):libraryState.openGroups.delete(kind);}
function renderPlaybooks(p=getProject('project-b')){$('#main').innerHTML=`<h1>打法库</h1>${libraryProjectPicker('playbooks',p)}<p>启用的打法放进当前项目负责人的上下文，只作参考；下次唤醒 / 派单生效。你可以查看、编辑、启用或停用。</p><section class="card"><h2>谁读哪些章节</h2><div class="table-scroll"><table class="handbook-roles"><thead><tr><th>角色</th><th>默认放进上下文的章节</th></tr></thead><tbody>${db.handbookRoles.map(r=>`<tr><th scope="row">${esc(r[0])}</th><td>${esc(r[1])}</td></tr>`).join('')}</tbody></table></div></section>${['卡片组合','卡片模板','workflow 模式'].map(kind=>`<details class="card playbook-group" data-playbook-kind="${kind}" ${libraryState.openGroups.has(kind)?'open':''} ontoggle="playbookGroupToggle(this,${js(kind)})"><summary>${kind==='卡片组合'?'打法 · ':''}${kind} · ${db.playbookLibrary.filter(t=>t.kind===kind).length} 项</summary>${db.playbookLibrary.filter(t=>t.kind===kind).map(t=>{const s=t.stats,enabled=p.enabledPlaybookIds?.includes(t.id);return `<article class="playbook-item" data-playbook-id="${esc(t.id)}"><h3>${esc(t.title)} <span class="play-status">${enabled?'✓ 已启用':'○ 已停用'}</span></h3><p>${esc(t.content)}</p><p class="src">内容来自 ${esc(t.source)}${t.edited?' · 你已编辑':''}</p><p>示例统计 · 被参考 ${s.references} 次 · 一次验收通过率 ${s.total?Math.round(s.firstPass/s.total*100)+'%（'+s.firstPass+'/'+s.total+'）':'暂无'} · 花费 ¥${s.cost.toFixed(2)} · 退回 ${s.returns} 次</p><button onclick="togglePlaybook(${js(t.id)})">${enabled?'停用':'启用'}</button> <button onclick="editPlaybook(${js(t.id)})">编辑</button>${libraryState.editing===t.id?`<label>名称<input id="play-title" value="${esc(t.title)}"></label><label>内容<textarea id="play-content">${esc(t.content)}</textarea></label><button onclick="savePlaybook(${js(t.id)})">保存打法</button> <button onclick="libraryState.editing=null;render()">取消编辑</button>`:''}</article>`;}).join('')}</details>`).join('')}<section class="card"><h2>待审核的新打法</h2>${db.playbookProposals.map(q=>`<article class="row"><h3>${esc(q.title)} · 示例</h3><p>${esc(q.content)}</p><p>${esc(q.reason)}</p>${q.status==='pending'?`<button onclick="reviewPlaybook(${js(q.id)},true)">通过</button> <button onclick="reviewPlaybook(${js(q.id)},false)">驳回</button>`:`<p>${q.status==='approved'?'已通过，入库后可启用':'已驳回'}</p><button onclick="decisionJump(${js(q.decisionId)})">查看决策</button>`}</article>`).join('')}</section>`;}
function executorUsability(version){const required=version.tests.filter(t=>t.id!=='I9-actions');return required.every(t=>t.status==='confirmed')?'可以使用':'不能使用';}
function renderExecutors(){$('#main').innerHTML=`<h1>执行者</h1><p>统一接口：启动、续接、取消、事件流、最终结果，向 ACP 靠拢；沙箱能力以测试为准。只有 Codex CLI 有适配器，首个真实执行任务必须补测。</p><p class="src">状态来自 FEATURES.md 7.2；测试展示为原型示例，不运行能力测试。未确认的必测能力阻止真实执行；代理配置可以先设计保存。</p>${db.executors.map(e=>`<section class="card executor-item"><h2>${esc(e.name)}</h2>${e.upcoming?'<span class="cap-upcoming">○ 即将支持</span>':e.versions.map(v=>`<h3>${esc(e.name)} ${esc(v.version)} · 示例展示</h3><span class="cap-blocked">⛔ ${executorUsability(v)} · 关键能力待测</span><div class="table-scroll"><table><thead><tr><th>必测项</th><th>状态</th><th>依据 / 缺少的测试</th></tr></thead><tbody>${v.tests.map(t=>`<tr data-capability="${esc(t.id)}"><th>${esc(t.id)} ${esc(t.name)}</th><td><span class="cap-${t.status}">${t.status==='confirmed'?'✓':'?'} ${esc(t.text)}</span>${t.id==='I9-actions'&&t.status!=='confirmed'?'<span class="cap-reminder">! 只算提醒</span>':''}</td><td>${esc(t.source)}</td></tr>`).join('')}</tbody></table></div>`).join('')}</section>`).join('')}<section class="card"><h2>接口能力与兜底</h2><p>续接缺失：新会话 + 交接上下文；结构化输出缺失：runtime 校验并重试；无工具能力缺失：读同成员、不写；无用量：花费标估算。</p></section>`;}
function reviewTool(id,accept){const q=byId(db.toolProposals,id);if(!q||q.status!=='pending')return {ok:false};q.status=accept?'approved':'rejected';if(accept){db.toolLibrary.push({...q,id:'tool-'+(++db.serial)});for(const id of q.boundAgents){const agent=getAgent(id);if(agent&&!agent.tools.includes(q.name))agent.tools.push(q.name);}}const d=recordDecision(null,null,(accept?'通过':'驳回')+'验证方法：'+q.name,'示例 · 来源 '+q.source);q.decisionId=d.id;render();return {ok:true};}
function upgradeGungnir(){if(db.gungnir.version===db.gungnir.next)return {ok:false};const before=db.gungnir.version;db.gungnir.version=db.gungnir.next;for(const t of db.toolLibrary)if(t.version===before)t.version=db.gungnir.version;recordDecision(null,null,'确认 Gungnir 版本升级',before+' → '+db.gungnir.version+'；示例 · 仅更新原型配置。');render();return {ok:true};}
function toolFields(t){return `<p>用途：${esc(t.purpose)}</p><p>权限：${esc(t.permissions)}</p><p>版本：${esc(t.version)} · 依赖：${esc(t.dependencies.join('、')||'无')}</p><p>绑定代理：${esc(db.agents.filter(a=>(a.tools||[]).some(x=>x===t.id||x===t.name)).map(a=>a.name).join('、')||'尚无')}</p>${t.kind==='验证方法'?`<p>什么时候测：${esc(t.when)}</p><p>怎么运行：${esc(t.run)}</p><p>结果怎么看：${esc(t.results)}</p><p>失败了去哪查：${esc(t.debug)}</p>`:''}`;}
function renderTools(){$('#main').innerHTML=`<h1>工具库</h1><section class="card"><h2>Gungnir · ${esc(db.gungnir.version)}</h2><p>按需导入技能与验证方法、固定版本；升级由你确认。新会话由 runtime 拉起，产物写进卡片与项目记忆。</p><button ${db.gungnir.version===db.gungnir.next?'disabled':''} onclick="upgradeGungnir()">确认升级至 ${esc(db.gungnir.next)} · 示例</button></section>${db.toolLibrary.map(t=>`<section class="card tool-item"><h2>${esc(t.name)} · ${esc(t.kind)}</h2>${toolFields(t)}</section>`).join('')}<section class="card"><h2>待审核的验证方法</h2>${db.toolProposals.map(t=>`<article class="row"><h3>${esc(t.name)} · 示例</h3>${toolFields(t)}<p>来源：${previewReference(t.source)}</p>${t.status==='pending'?`<button onclick="reviewTool(${js(t.id)},true)">通过入库</button> <button onclick="reviewTool(${js(t.id)},false)">驳回</button>`:`<p>${t.status==='approved'?'已入库':'已驳回'}</p><button onclick="decisionJump(${js(t.decisionId)})">查看决策</button>`}</article>`).join('')}</section>`;}
function renderSettings029(p){return `<section class="card"><h2>项目负责人的代理配置</h2><p>${esc(getAgent(p.leaderId)?.name)} · 执行者 ${esc(getAgent(p.leaderId)?.executor)} · 模型 ${esc(getAgent(p.leaderId)?.mainModel)} · 强度 ${esc(getAgent(p.leaderId)?.mainStrength)}</p><p>专业指令：${esc(getAgent(p.leaderId)?.instructions)}</p><button onclick="go('agents',${js(p.id)})">查看代理库</button><button onclick="go('executors',${js(p.id)})">查看执行者配置与能力测试</button></section><section class="card"><h2>启用的打法</h2><p>${esc(enabledPlaybooks(p).map(t=>t.title).join('、')||'无')}</p><p class="src">下次唤醒 / 派单放入项目负责人的上下文，只作参考。</p><button onclick="go('playbooks',${js(p.id)})">管理启用的打法</button></section><section class="card settings-editor"><h2>预设指派规则</h2><label>匹配条件、代理与 runtime 行为<textarea id="setting-assignmentRules">${esc(p.assignmentRules)}</textarea></label><button onclick="saveProjectSetting(${js(p.id)},'assignmentRules',$('#setting-assignmentRules').value)">保存预设指派规则</button><h2>运行资源模板</h2><label>端口、数据库、初始化与销毁、输出目录、共享目录、复制文件、部署命令<textarea id="setting-resourceTemplate">${esc(p.resourceTemplate)}</textarea></label><button onclick="saveProjectSetting(${js(p.id)},'resourceTemplate',$('#setting-resourceTemplate').value)">保存运行资源模板</button><h2>禁止动作清单</h2><label>命令和动作<textarea id="setting-forbiddenActions">${esc(p.forbiddenActions)}</textarea></label><p class="cap-reminder">! 只算提醒 · 当前执行者禁止动作能力未测，真实执行不能依赖此清单拦截。</p><button onclick="saveProjectSetting(${js(p.id)},'forbiddenActions',$('#setting-forbiddenActions').value)">保存禁止动作清单</button><p class="src">示例 · 原型保存文字配置，不解析任意自然语言或执行命令。</p><p id="settings-feedback" role="status">${esc(p.settingsNotice||'')}</p></section><section class="card"><h2>项目与答疑预算</h2><label>项目上限（元）<input id="setting-projectBudget" type="number" min="0" step=".01" value="${p.budget}"></label><label>答疑上限（元）<input id="setting-answerBudget" type="number" min="0" step=".01" value="${p.answerBudget.limit}"></label><button onclick="saveBudgets(${js(p.id)},$('#setting-projectBudget').value,$('#setting-answerBudget').value)">保存预算</button></section>`;}
function saveProjectSetting(id,key,value){const p=getProject(id),names={assignmentRules:'预设指派规则',resourceTemplate:'运行资源模板',forbiddenActions:'禁止动作清单'};if(!p||!names[key]||!String(value||'').trim())return {ok:false};const before=p[key];p[key]=String(value).trim();p.settingsNotice='已保存'+names[key];recordDecision(id,null,'修改'+names[key],'修改前：'+before+'；修改后：'+p[key]);render();return {ok:true};}
function saveBudgets(id,budget,answerBudget){const p=getProject(id),total=Number(budget),answer=Number(answerBudget);if(!p||!String(budget).trim()||!String(answerBudget).trim()||!Number.isFinite(total)||!Number.isFinite(answer)||total<p.spent||answer<p.answerBudget.spent){p.settingsNotice='上限必须是有效数字且不小于已用花费。';render();return {ok:false};}p.budget=total;p.answerBudget.limit=answer;recordDecision(id,null,'修改项目与答疑预算','项目 ¥'+total+'；答疑 ¥'+answer);p.settingsNotice='预算已保存';render();return {ok:true};}
function revealFocusTarget(target){if(!target)return;for(let n=target.parentElement;n;n=n.parentElement)if(n.tagName==='DETAILS'&&!n.open){n.open=true;if(n.dataset.status)boardState.openColumns.add(n.dataset.status);}let r=target.getBoundingClientRect?.();if(!r)return;const right=r.right??r.left+r.width,bottom=r.bottom??r.top+r.height;let outside=r.left<0||r.top<0||right>(window.innerWidth||1280)||(window.innerHeight>0&&bottom>window.innerHeight);for(let n=target.parentElement;n;n=n.parentElement){if(n.clientWidth&&n.scrollWidth>n.clientWidth||n.clientHeight&&n.scrollHeight>n.clientHeight){const b=n.getBoundingClientRect?.();if(b&&(r.left<b.left||r.top<b.top||right>(b.right??b.left+b.width)||bottom>(b.bottom??b.top+b.height)))outside=true;}}if(outside)target.scrollIntoView?.({block:'nearest',inline:'nearest',behavior:'instant'});}
